export interface PeriodTiming {
  start: string;
  end: string;
  isBreak?: boolean;
  label?: string;
}

export const DEFAULT_TIMINGS: PeriodTiming[] = [
  { start: '8:00 AM', end: '9:00 AM' },
  { start: '9:00 AM', end: '10:00 AM' },
  { start: '10:00 AM', end: '11:00 AM' },
  { start: '11:00 AM', end: '11:15 AM', isBreak: true, label: 'Short Break' },
  { start: '11:15 AM', end: '12:15 PM' },
  { start: '12:15 PM', end: '1:15 PM' },
  { start: '1:15 PM', end: '2:00 PM', isBreak: true, label: 'Lunch Break' },
  { start: '2:00 PM', end: '3:00 PM' },
  { start: '3:00 PM', end: '4:00 PM' },
];

interface AppContextValue {
  leaveRequests: LeaveRequest[];
  notifications: Notification[];
  unreadCount: number;
  timetable: SchoolTimetable;
  periodTimings: PeriodTiming[];
  academicYears: { id: string; name: string; is_current: boolean }[];
  selectedAcademicYearId: string;
  setSelectedAcademicYearId: (id: string) => void;
  addLeaveRequest: (req: Omit<LeaveRequest, 'id' | 'appliedOn'>) => Promise<void>;
  approveLeave: (id: string) => Promise<void>;
  rejectLeave: (id: string, notes?: string) => Promise<void>;
  markNotificationsRead: () => void;
  setTimetablePeriod: (className: string, day: string, periodIndex: number, period: TimetablePeriod | null) => void;
  savePeriodTimings: (newTimings: PeriodTiming[]) => Promise<void>;
  hasUnsavedChanges: boolean;
  setHasUnsavedChanges: (val: boolean) => void;
}

const AppContext = createContext<AppContextValue | null>(null);

export const TIMETABLE_DAYS = DAYS;
export const TIMETABLE_PERIODS = PERIODS;

export const PERIOD_TIMES = [
  '8:00 AM', '9:00 AM', '10:00 AM', '11:00 AM',
  '12:00 PM', '1:00 PM', '2:00 PM', '3:00 PM',
];

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [leaveRequests, setLeaveRequests] = useState<LeaveRequest[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [timetable, setTimetable] = useState<SchoolTimetable>(buildDefaultTimetable);
  const [periodTimings, setPeriodTimings] = useState<PeriodTiming[]>(() => {
    const saved = localStorage.getItem('timetable_period_timings');
    return saved ? JSON.parse(saved) : DEFAULT_TIMINGS;
  });
  const [academicYears, setAcademicYears] = useState<{ id: string; name: string; is_current: boolean }[]>([]);
  const [selectedAcademicYearId, setSelectedAcademicYearIdState] = useState<string>(() => {
    return localStorage.getItem('selected_academic_year_id') || '';
  });

  const setSelectedAcademicYearId = (id: string) => {
    setSelectedAcademicYearIdState(id);
    localStorage.setItem('selected_academic_year_id', id);
  };

  const { user } = useAuth();

  useEffect(() => {
    if (!user) {
      setLeaveRequests([]);
      setNotifications([]);
      setTimetable(buildDefaultTimetable());
      setAcademicYears([]);
      return;
    }

    async function loadInitialData() {
      // Load Academic Years
      try {
        const ays = await api.getResources('academic-years');
        if (ays && ays.length > 0) {
          const mapped = ays.map((ay: any) => ({
            id: String(ay.id),
            name: ay.name,
            is_current: !!ay.is_current,
          }));
          setAcademicYears(mapped);

          const savedId = localStorage.getItem('selected_academic_year_id');
          if (!savedId) {
            const current = mapped.find((ay: any) => ay.is_current) || mapped[0];
            setSelectedAcademicYearId(current.id);
          }
        }
      } catch (err) {
        console.error('Error loading academic years in AppContext:', err);
      }

      // Load leaves
      try {
        const leavesData = await api.getResources('leaves');
        if (leavesData) {
          const mappedLeaves = leavesData.map((d: any) => ({
            id: String(d.id),
            staffId: String(d.user_id),
            staffName: d.staff_name || 'Staff Member',
            init: d.init || (d.staff_name ? d.staff_name.split(' ').map((n: any) => n[0] ?? '').join('') : 'SM'),
            type: (typeof d.leave_type === 'object' && d.leave_type ? d.leave_type.name : d.leave_type) || 'Sick Leave',
            from: d.start_date || d.from,
            to: d.end_date || d.to,
            days: d.days || 1,
            reason: d.reason || '',
            status: d.status || 'Pending',
            appliedOn: d.created_at ? d.created_at.slice(0, 10) : new Date().toISOString().slice(0, 10),
            adminNotes: d.admin_notes || '',
          }));
          setLeaveRequests(mappedLeaves);
        }
      } catch (err) {
        console.error('Error loading leaves in AppContext:', err);
      }

      // Load notifications
      try {
        const notifData = await api.getResources('notifications').catch(() => []);
        setNotifications((notifData || []).map((n: any) => ({
          id: String(n.id),
          type: n.type || 'leave_request',
          message: n.message,
          time: 'Recently',
          read: !!n.read_at,
        })));
      } catch (err) {
        console.error('Error loading notifications in AppContext:', err);
      }

      // Fetch all database settings to restore to localStorage on app boot
      try {
        const allSettings = await api.getResources('settings');
        if (Array.isArray(allSettings)) {
          const keysToExclude = ['token', 'user'];
          allSettings.forEach((setting: any) => {
            if (setting.key && !keysToExclude.includes(setting.key) && setting.value !== undefined) {
              // Write directly using localStorage.setItem to bypass monkey-patch background writes
              localStorage.setItem(setting.key, setting.value);

              // Explicitly load period timings state if present
              if (setting.key === 'timetable_period_timings') {
                try {
                  setPeriodTimings(JSON.parse(setting.value));
                } catch (e) {
                  console.error('Failed to parse timetable_period_timings:', e);
                }
              }
            }
          });
        }
      } catch (err) {
        console.error('Error loading DB settings to localStorage in AppContext:', err);
      }

      // Fetch timetable from database
      try {
        const timetableData = await api.getResources('timetable', { limit: '1000' });
        if (timetableData && timetableData.length > 0) {
          const dayMap: Record<string, string> = {
            '2026-06-01': 'Monday',
            '2026-06-02': 'Tuesday',
            '2026-06-03': 'Wednesday',
            '2026-06-04': 'Thursday',
            '2026-06-05': 'Friday',
            '2026-06-06': 'Saturday',
          };

          const loadedTimetable: SchoolTimetable = {};
          const classes = ['6A', '6B', '7A', '7B', '8A', '8B', '9A', '9B', '10A', '10B'];
          for (const cls of classes) {
            loadedTimetable[cls] = {};
            for (const day of ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']) {
              loadedTimetable[cls][day] = {};
              for (let p = 0; p < 12; p++) {
                loadedTimetable[cls][day][p] = null;
              }
            }
          }

          timetableData.forEach((slot: any) => {
            const rawCls = slot.batch_name;
            if (!rawCls) return;

            const cls = rawCls.trim();
            const day = slot.day || dayMap[slot.date];
            const p = slot.period;
            if (day && p !== undefined && p >= 0 && p < 12) {
              // Dynamically initialize class and day structures if not present
              if (!loadedTimetable[cls]) {
                loadedTimetable[cls] = {};
              }
              if (!loadedTimetable[cls][day]) {
                loadedTimetable[cls][day] = {};
                for (let i = 0; i < 12; i++) {
                  loadedTimetable[cls][day][i] = null;
                }
              }

              loadedTimetable[cls][day][p] = {
                subject: slot.subject,
                teacher: slot.teacher,
                teacherId: String(slot.teacherId),
                room: slot.room,
              };
            }
          });
          setTimetable(loadedTimetable);
        }
      } catch (tErr) {
        console.error('Error loading timetable in AppContext:', tErr);
      }

      // Delay pre-fetching of non-critical tab resources by 1.5 seconds
      setTimeout(() => {
        api.getResources('students', { with: 'batch.academicYear', limit: '1000' }).catch(() => {});
        api.getResources('batches').catch(() => {});
        api.getResources('holidays').catch(() => {});
        api.getSubstituteStaff().catch(() => {});
        api.getResources('daily-diaries').catch(() => {});
        api.getResources('fee-categories').catch(() => {});
        api.getResources('student-fees', { limit: '10000' }).catch(() => {});
        api.getResources('faculty').catch(() => {});
        api.getResources('expenses').catch(() => {});
        api.getResources('settings').catch(() => {});
        api.getResources('settings', { key: 'kts_student_attendance_records' }).catch(() => {});
        api.getResources('settings', { key: 'kts_holidays' }).catch(() => {});
        api.getResources('settings', { key: 'examinations_exams' }).catch(() => {});
        api.getResources('settings', { key: 'kts_student_marks' }).catch(() => {});
        api.getResources('settings', { key: 'examinations_schedules' }).catch(() => {});
        api.getResources('payslips').catch(() => {});
        api.getResources('biometric-logs').catch(() => {});
        api.getResources('homework').catch(() => {});
        api.getResources('alumni').catch(() => {});
      }, 1500);
    }
    loadInitialData();
  }, [user]);

  const unreadCount = notifications.filter((n) => !n.read).length;

  const addLeaveRequest = async (req: Omit<LeaveRequest, 'id' | 'appliedOn'>) => {
    try {
      const res = await api.createResource('leaves', {
        user_id: parseInt(req.staffId) || 1,
        staff_name: req.staffName,
        leave_type: req.type,
        start_date: req.from,
        end_date: req.to,
        days: req.days,
        reason: req.reason,
        status: 'Pending',
      });

      const newReq: LeaveRequest = {
        ...req,
        id: String(res.id),
        appliedOn: new Date().toISOString().slice(0, 10),
        status: 'Pending',
        adminNotes: '',
      };
      setLeaveRequests((prev) => [newReq, ...prev]);

      const notif: Notification = {
        id: 'n' + res.id,
        type: 'leave_request',
        message: `${req.staffName} applied for ${req.type} (${req.from})`,
        time: 'Just now',
        read: false,
        refId: String(res.id),
      };
      setNotifications((prev) => [notif, ...prev]);
    } catch (err) {
      console.error('Error adding leave request:', err);
    }
  };

  const approveLeave = async (id: string) => {
    try {
      await api.updateResource('leaves', id, { status: 'Approved' });
      setLeaveRequests((prev) =>
        prev.map((l) => (l.id === id ? { ...l, status: 'Approved' } : l))
      );
      const req = leaveRequests.find((l) => l.id === id);
      if (req) {
        const notif: Notification = {
          id: 'na' + id,
          type: 'leave_approved',
          message: `Your ${req.type} request has been approved`,
          time: 'Just now',
          read: false,
          refId: id,
        };
        setNotifications((prev) => [notif, ...prev]);
      }
    } catch (err) {
      console.error('Error approving leave:', err);
    }
  };

  const rejectLeave = async (id: string, notes?: string) => {
    try {
      await api.updateResource('leaves', id, { status: 'Rejected', admin_notes: notes });
      setLeaveRequests((prev) =>
        prev.map((l) => (l.id === id ? { ...l, status: 'Rejected', adminNotes: notes } : l))
      );
      const req = leaveRequests.find((l) => l.id === id);
      if (req) {
        const notif: Notification = {
          id: 'nr' + id,
          type: 'leave_rejected',
          message: `Your ${req.type} request has been rejected.${notes ? ` Reason: ${notes}` : ''}`,
          time: 'Just now',
          read: false,
          refId: id,
        };
        setNotifications((prev) => [notif, ...prev]);
      }
    } catch (err) {
      console.error('Error rejecting leave:', err);
    }
  };

  const markNotificationsRead = () => {
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  };

  const setTimetablePeriod = (
    className: string,
    day: string,
    periodIndex: number,
    period: TimetablePeriod | null
  ) => {
    setTimetable((prev) => ({
      ...prev,
      [className]: {
        ...prev[className],
        [day]: {
          ...(prev[className]?.[day] ?? {}),
          [periodIndex]: period,
        },
      },
    }));
  };

  const savePeriodTimings = async (newTimings: PeriodTiming[]) => {
    setPeriodTimings(newTimings);
    localStorage.setItem('timetable_period_timings', JSON.stringify(newTimings));
    try {
      const valueStr = JSON.stringify(newTimings);
      const existing = await api.getResources('settings', { key: 'timetable_period_timings' });
      if (Array.isArray(existing) && existing.length > 0) {
        const settingId = existing[0].id;
        await api.updateResource('settings', String(settingId), { value: valueStr });
      } else {
        await api.createResource('settings', {
          key: 'timetable_period_timings',
          value: valueStr,
          group: 'timetable',
          type: 'json',
          is_public: true,
        });
      }
    } catch (err) {
      console.error('Error saving period timings to DB:', err);
    }
  };

  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  useEffect(() => {
    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      if (hasUnsavedChanges) {
        e.preventDefault();
        e.returnValue = '';
      }
    };
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [hasUnsavedChanges]);

  return (
    <AppContext.Provider value={{
      leaveRequests,
      notifications,
      unreadCount,
      timetable,
      periodTimings,
      academicYears,
      selectedAcademicYearId,
      setSelectedAcademicYearId,
      addLeaveRequest,
      approveLeave,
      rejectLeave,
      markNotificationsRead,
      setTimetablePeriod,
      savePeriodTimings,
      hasUnsavedChanges,
      setHasUnsavedChanges,
    }}>
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used within AppProvider');
  return ctx;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import type { User } from '../types';
import { api, ApiError } from '../services/api';

interface AuthContextValue {
  user: User | null;
  login: (email: string, password: string) => Promise<{ ok: boolean; error?: string }>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    async function refreshUser() {
      const token = localStorage.getItem('token');
      // Skip API call for demo token — no backend needed
      if (token && token !== 'demo-token') {
        try {
          const res = await api.getMe();
          if (res.user) {
            setUser(res.user);
            localStorage.setItem('user', JSON.stringify(res.user));
          }
        } catch (e) {
          // Only logout on a real 401 (token truly invalid/expired).
          // Network errors, 5xx server errors, or CORS failures are transient
          // and should NOT kick the user out — keep them on their cached session.
          if (e instanceof ApiError && e.status === 401) {
            logout();
          } else {
            console.warn('Could not refresh session (non-auth error, keeping user logged in):', e);
          }
        }
      }
    }

    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      try {
        setUser(JSON.parse(savedUser));
      } catch (e) {
        localStorage.removeItem('user');
      }
    }
    refreshUser();
  }, []);

  // Listen for 401 Unauthorized events dispatched by api.ts
  // This replaces the old `window.location.href = '/login'` hard redirect,
  // which could land on the Laravel backend's /login page in production instead of the SPA.
  useEffect(() => {
    const handleUnauthorized = () => {
      api.logout();
      localStorage.removeItem('user');
      setUser(null);
    };
    window.addEventListener('kts:unauthorized', handleUnauthorized);
    return () => window.removeEventListener('kts:unauthorized', handleUnauthorized);
  }, []);

  // Poll server to check if user status has been changed to inactive while logged in

  useEffect(() => {
    if (!user) return;
    // Skip polling for demo users — no backend to verify against
    const token = localStorage.getItem('token');
    if (token === 'demo-token') return;

    const interval = setInterval(async () => {
      try {
        const res = await api.getMe();
        if (res.user && res.user.status && res.user.status.toLowerCase() === 'inactive') {
          logout();
          alert('Account is inactive, contact admin.');
        }
      } catch (e) {
        // Only logout for a confirmed 403 "account inactive" response from the server.
        // Any other error (network timeout, 500, CORS, etc.) is a TRANSIENT issue —
        // logging the user out for a wifi blip is very bad UX.
        if (e instanceof ApiError && e.status === 403) {
          logout();
          alert((e as Error).message || 'Account is inactive, contact admin.');
        } else if (e instanceof ApiError && e.status === 401) {
          // 401 is already handled by kts:unauthorized event in api.ts — skip duplicate action
          console.warn('Session expired (handled by kts:unauthorized)');
        } else {
          // Transient error — silently ignore and keep user logged in
          console.warn('Polling /me failed (transient, keeping session):', e);
        }
      }
    }, 15000);

    return () => clearInterval(interval);
  }, [user]);

  // Listen for storage changes to sync authentication state and force logouts across tabs
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      // If storage was cleared entirely
      if (!e.key) {
        if (!localStorage.getItem('token')) {
          setUser(null);
        }
        return;
      }

      // Handle force logout flag
      if (user) {
        const expectedKey = `kts_force_logout_${user.email?.toLowerCase()}`;
        if (e.key === expectedKey && e.newValue) {
          logout();
          alert('You have been logged out by an administrator.');
          return;
        }
      }

      // Sync user state changes (e.g. login/role switch in another tab)
      if (e.key === 'user') {
        if (e.newValue) {
          try {
            const parsedUser = JSON.parse(e.newValue);
            if (JSON.stringify(user) !== JSON.stringify(parsedUser)) {
              setUser(parsedUser);
            }
          } catch (err) {
            setUser(null);
          }
        } else {
          setUser(null);
        }
      }

      // Sync token change (e.g. logout in another tab)
      if (e.key === 'token') {
        if (!e.newValue) {
          setUser(null);
        } else {
          const savedUser = localStorage.getItem('user');
          if (savedUser) {
            try {
              const parsedUser = JSON.parse(savedUser);
              if (JSON.stringify(user) !== JSON.stringify(parsedUser)) {
                setUser(parsedUser);
              }
            } catch (err) {}
          }
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [user]);

  // Demo users for offline / no-backend usage
  const DEMO_USERS: Record<string, { email: string; password: string; user: User }> = {
    'admin@krishnaveni.edu': {
      email: 'admin@krishnaveni.edu',
      password: 'admin123',
      user: {
        id: '1',
        name: 'Admin User',
        email: 'admin@krishnaveni.edu',
        role: 'admin',
        initials: 'AU',
        designation: 'Administrator',
      },
    },
    'teacher@krishnaveni.edu': {
      email: 'teacher@krishnaveni.edu',
      password: 'teacher123',
      user: {
        id: '2',
        name: 'Teacher User',
        email: 'teacher@krishnaveni.edu',
        role: 'teacher',
        initials: 'TU',
        designation: 'Teacher',
      },
    },
  };

  const login = async (email: string, password: string) => {
    try {
      const res = await api.login({ email, password });
      if (res.user) {
        setUser(res.user);
        localStorage.setItem('user', JSON.stringify(res.user));
        return { ok: true };
      }
      return { ok: false, error: 'Login failed' };
    } catch (e) {
      // Check if credentials match a demo user as a fallback (works without backend or database seeding)
      const demo = DEMO_USERS[email.trim().toLowerCase()];
      if (demo && password === demo.password) {
        localStorage.setItem('token', 'demo-token');
        localStorage.setItem('user', JSON.stringify(demo.user));
        setUser(demo.user);
        return { ok: true };
      }
      return { ok: false, error: (e as Error).message || 'Invalid credentials. Please check your email and password.' };
    }
  };

  const logout = () => {
    api.logout();
    localStorage.removeItem('user');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

import { useState, useEffect } from 'react';
import { CheckCircle, XCircle, Users, Calendar, Clock, Save, Loader2, Search, Check, AlertCircle } from 'lucide-react';
import { Card } from '../components/Card';
import { Badge } from '../components/Badge';
import { Avatar } from '../components/ui';
import { useAuth } from '../context/AuthContext';
import { useApp } from '../context/AppContext';
import { api } from '../services/api';

interface Student {
  id: string;
  name: string;
  roll: string;
  class: string;
  section: string;
  status: string;
}

interface Batch {
  id: string;
  name: string;
  class_teacher_id?: number;
  class_teacher_name?: string;
}

// Custom interface for local storage/database synced attendance entries
export interface StudentPeriodAttendance {
  studentId: string;
  studentName: string;
  roll: string;
  className: string;
  date: string; // YYYY-MM-DD
  session: 'first_period' | 'lunch_period';
  status: 'present' | 'absent';
  markedBy: string;
  markedById: string;
  markedAt: string;
}

async function saveSettingToDb(key: string, value: any) {
  try {
    const valueStr = typeof value === 'string' ? value : JSON.stringify(value);
    const existing = await api.getResources('settings', { key });
    if (Array.isArray(existing) && existing.length > 0) {
      const settingId = existing[0].id;
      await api.updateResource('settings', String(settingId), { value: valueStr });
    } else {
      await api.createResource('settings', {
        key,
        value: valueStr,
        group: 'attendance',
        type: 'json',
        is_public: true,
      });
    }
  } catch (err) {
    console.error(`Error saving setting ${key} to DB:`, err);
  }
}

export function AllotAttendance() {
  const { user } = useAuth();
  const { timetable, periodTimings } = useApp();

  const getLocalDateString = () => {
    const d = new Date();
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const [date, setDate] = useState<string>(getLocalDateString());
  const [batches, setBatches] = useState<Batch[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [attendanceRecords, setAttendanceRecords] = useState<StudentPeriodAttendance[]>([]);

  const [selectedClass, setSelectedClass] = useState<string>('');
  const [session, setSession] = useState<'first_period' | 'lunch_period'>('first_period');
  const [substituteAssignments, setSubstituteAssignments] = useState<any[]>([]);

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [savedMsg, setSavedMsg] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Student selection state (studentId -> present/absent)
  const [statusMap, setStatusMap] = useState<Record<string, 'present' | 'absent'>>({});
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [isLocked, setIsLocked] = useState(false);

  // Day of week from selected date
  const getDayName = (dateStr: string) => {
    const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const d = new Date(dateStr + 'T00:00:00');
    return days[d.getDay()] || 'Monday';
  };

  const dayOfWeek = getDayName(date);

  // Load initial data
  useEffect(() => {
    async function loadData() {
      setLoading(true);
      try {
        const [batchesData, studentsData] = await Promise.all([
          api.getResources('batches', { limit: '1000' }).catch(() => []),
          api.getResources('students', { limit: '1000' }).catch(() => [])
        ]);

        setBatches(batchesData.map((b: any) => ({
          id: String(b.id),
          name: b.name,
          class_teacher_id: b.class_teacher_id || undefined,
          class_teacher_name: b.class_teacher_name || undefined
        })));

        setStudents(studentsData.map((s: any) => ({
          id: String(s.id),
          name: s.name,
          roll: s.enrollment_number || 'N/A',
          class: s.class || '8',
          section: s.section || 'A',
          status: s.status || 'active'
        })));

        // Load and sync attendance records from settings
        const settingsRes = await api.getResources('settings', { key: 'kts_student_attendance_records' });
        if (Array.isArray(settingsRes) && settingsRes.length > 0 && settingsRes[0].value) {
          try {
            const parsed = JSON.parse(settingsRes[0].value);
            setAttendanceRecords(parsed);
            localStorage.setItem('kts_student_attendance_records', JSON.stringify(parsed));
          } catch (e) {
            console.error('Error parsing kts_student_attendance_records:', e);
          }
        } else {
          const local = localStorage.getItem('kts_student_attendance_records');
          if (local) {
            setAttendanceRecords(JSON.parse(local));
          }
        }
      } catch (err) {
        console.error('Error loading data for allotment:', err);
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  // Load substitute assignments for the selected date
  useEffect(() => {
    if (!user || !date) return;
    const substituteUserId = user.id;
    async function loadSubstituteAssignments() {
      try {
        const res = await api.getResources('substitute-assignments', {
          substitute_user_id: substituteUserId,
          assignment_date: date,
          status: 'assigned'
        });
        if (Array.isArray(res)) {
          setSubstituteAssignments(res);
        } else {
          setSubstituteAssignments([]);
        }
      } catch (err) {
        console.error('Error loading substitute assignments:', err);
        setSubstituteAssignments([]);
      }
    }
    loadSubstituteAssignments();
  }, [user, date]);

  // Determine first period after lunch index
  const getLunchPeriodIndex = () => {
    const lunchIdx = periodTimings.findIndex(t => t.isBreak && t.label?.toLowerCase().includes('lunch'));
    if (lunchIdx === -1) return 7; // fallback default

    // Find next non-break period
    for (let i = lunchIdx + 1; i < periodTimings.length; i++) {
      if (!periodTimings[i].isBreak) {
        return i; // Return direct index in periodTimings
      }
    }
    return 7;
  };

  const lunchPeriodIndex = getLunchPeriodIndex();

  // Determine teacher access: which classes can they take attendance for today?
  const allowedClasses = batches.filter(batch => {
    // 1. Is class teacher? (First period access)
    const isClassTeacher = String(batch.class_teacher_id) === String(user?.id) || 
      (batch.class_teacher_name && batch.class_teacher_name.toLowerCase() === user?.name?.toLowerCase());

    // 2. Teaches first period after lunch today? (Lunch period access)
    const classTimetable = timetable[batch.name] ?? {};
    const todaySlots = classTimetable[dayOfWeek] ?? {};

    // Find the slot for the first period after lunch (no offset subtraction since lunchPeriodIndex is the raw slot index)
    const lunchSlot = todaySlots[lunchPeriodIndex]; 
    const teachesAfterLunch = lunchSlot && (
      String(lunchSlot.teacherId) === String(user?.id) || 
      (lunchSlot.teacher && lunchSlot.teacher.toLowerCase() === user?.name?.toLowerCase())
    );

    // 3. Is substitute teacher for the first period of this batch today?
    const isSubstituteFirstPeriod = substituteAssignments.some(sa => 
      sa.timetable?.batch?.name === batch.name && 
      (sa.timetable?.time_slot_id - 1) === 0
    );

    // 4. Is substitute teacher for the first period after lunch of this batch today?
    const isSubstituteAfterLunch = substituteAssignments.some(sa => 
      sa.timetable?.batch?.name === batch.name && 
      (sa.timetable?.time_slot_id - 1) === lunchPeriodIndex
    );

    return isClassTeacher || teachesAfterLunch || isSubstituteFirstPeriod || isSubstituteAfterLunch;
  }).map(b => b.name);

  // Set default class if not set or not in allowed classes
  useEffect(() => {
    if (allowedClasses.length > 0 && (!selectedClass || !allowedClasses.includes(selectedClass))) {
      setSelectedClass(allowedClasses[0]);
    }
  }, [allowedClasses, selectedClass]);

  // Determine available sessions for selected class today
  const selectedBatchObj = batches.find(b => b.name === selectedClass);
  const isClassTeacherForSelected = selectedBatchObj && (
    String(selectedBatchObj.class_teacher_id) === String(user?.id) || 
    (selectedBatchObj.class_teacher_name && selectedBatchObj.class_teacher_name.toLowerCase() === user?.name?.toLowerCase())
  );

  const classTimetable = timetable[selectedClass] ?? {};
  const todaySlots = classTimetable[dayOfWeek] ?? {};
  const lunchSlot = todaySlots[lunchPeriodIndex];
  const teachesAfterLunchForSelected = lunchSlot && (
    String(lunchSlot.teacherId) === String(user?.id) || 
    (lunchSlot.teacher && lunchSlot.teacher.toLowerCase() === user?.name?.toLowerCase())
  );

  const isSubstituteFirstPeriodForSelected = substituteAssignments.some(sa => 
    sa.timetable?.batch?.name === selectedClass && 
    (sa.timetable?.time_slot_id - 1) === 0
  );

  const isSubstituteAfterLunchForSelected = substituteAssignments.some(sa => 
    sa.timetable?.batch?.name === selectedClass && 
    (sa.timetable?.time_slot_id - 1) === lunchPeriodIndex
  );

  useEffect(() => {
    if (selectedClass) {
      const hasFirstPeriod = isClassTeacherForSelected || isSubstituteFirstPeriodForSelected;
      const hasAfterLunch = teachesAfterLunchForSelected || isSubstituteAfterLunchForSelected;

      if (hasFirstPeriod && !hasAfterLunch) {
        setSession('first_period');
      } else if (!hasFirstPeriod && hasAfterLunch) {
        setSession('lunch_period');
      }
    }
  }, [
    selectedClass, 
    isClassTeacherForSelected, 
    teachesAfterLunchForSelected, 
    isSubstituteFirstPeriodForSelected, 
    isSubstituteAfterLunchForSelected
  ]);

  // Filter students in selected class (active status only)
  const classStudents = students.filter(s => {
    const studentClassFormatted = `${s.class}${s.section}`;
    return studentClassFormatted.toLowerCase() === selectedClass.toLowerCase() && s.status.toLowerCase() === 'active';
  });

  // Load existing attendance status if already marked
  useEffect(() => {
    if (selectedClass && session && date) {
      const initialMap: Record<string, 'present' | 'absent'> = {};
      classStudents.forEach(s => {
        initialMap[s.id] = 'present'; // default to present
      });

      const records = attendanceRecords.filter(
        r => r.className.toLowerCase() === selectedClass.toLowerCase() &&
             r.session === session &&
             r.date === date
      );

      records.forEach(r => {
        initialMap[r.studentId] = r.status;
      });

      setStatusMap(initialMap);
      setIsLocked(records.length > 0);
    }
  }, [selectedClass, session, date, attendanceRecords, students]);

  // Search filter
  const filteredStudents = classStudents.filter(
    s => s.name.toLowerCase().includes(searchQuery.toLowerCase()) || s.roll.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleSubmit = async () => {
    setSaving(true);
    try {
      const timestamp = new Date().toISOString();
      const newEntries: StudentPeriodAttendance[] = classStudents.map(s => ({
        studentId: s.id,
        studentName: s.name,
        roll: s.roll,
        className: selectedClass,
        date: date,
        session: session,
        status: statusMap[s.id] || 'present',
        markedBy: user?.name || 'Teacher',
        markedById: user?.id || '1',
        markedAt: timestamp
      }));

      // Filter out old records for the same class, session, and date
      const otherRecords = attendanceRecords.filter(
        r => !(r.className.toLowerCase() === selectedClass.toLowerCase() &&
               r.session === session &&
               r.date === date)
      );

      const updatedRecords = [...otherRecords, ...newEntries];
      setAttendanceRecords(updatedRecords);
      localStorage.setItem('kts_student_attendance_records', JSON.stringify(updatedRecords));
      await saveSettingToDb('kts_student_attendance_records', updatedRecords);

      // Trigger cache invalidation so the changes show up in admin dashboards immediately
      try {
        await api.createResource('attendance/invalidate-cache', { timestamp });
      } catch (e) {
        // ignore if endpoint doesn't exist
      }

      setSavedMsg(true);
      setIsLocked(true);
      setTimeout(() => setSavedMsg(false), 2500);
    } catch (err) {
      console.error('Failed to save student attendance:', err);
    } finally {
      setSaving(false);
    }
  };

  const toggleStudent = (studentId: string) => {
    if (isLocked) return;
    setStatusMap(prev => ({
      ...prev,
      [studentId]: prev[studentId] === 'present' ? 'absent' : 'present'
    }));
  };

  const markAll = (status: 'present' | 'absent') => {
    if (isLocked) return;
    const updated = { ...statusMap };
    classStudents.forEach(s => {
      updated[s.id] = status;
    });
    setStatusMap(updated);
  };

  const presentCount = Object.values(statusMap).filter(s => s === 'present').length;
  const absentCount = Object.values(statusMap).filter(s => s === 'absent').length;

  return (
    <div className="flex-1 overflow-y-auto p-3.5 bg-[var(--bg)]">
      {/* Header */}
      <div className="bg-gradient-to-r from-[var(--purple)] to-[#7c3aed] rounded-2xl p-4 mb-3.5 text-white relative overflow-hidden">
        <div className="absolute right-4 top-4 opacity-10">
          <Users size={64} />
        </div>
        <div className="relative z-10">
          <div className="text-[11px] font-medium opacity-70 uppercase tracking-wider mb-1">Teacher Portal</div>
          <div className="text-[18px] font-bold mb-1">Student Attendance Allotment</div>
          <div className="text-[12px] opacity-80">Mark daily attendance for your class-teacher sections and lunch break periods.</div>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center items-center py-16">
          <Loader2 size={24} className="animate-spin text-[var(--blue-tx)]" />
        </div>
      ) : (
        <div className="space-y-3.5">
          {/* Controls Panel */}
          <Card>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
              {/* Date selector */}
              <div>
                <label className="block text-[11px] font-medium text-[var(--tx3)] uppercase mb-1.5 flex items-center gap-1">
                  <Calendar size={11} /> Date
                </label>
                <input
                  type="date"
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] outline-none focus:border-[var(--blue)] cursor-pointer"
                />
              </div>

              {/* Class selector */}
              <div>
                <label className="block text-[11px] font-medium text-[var(--tx3)] uppercase mb-1.5 flex items-center gap-1">
                  <Users size={11} /> Class / Section
                </label>
                {allowedClasses.length === 0 ? (
                  <div className="text-[11.5px] text-[var(--red-tx)] bg-[var(--red-bg)] px-3 py-2 rounded-lg border border-[var(--red-tx)]/10 font-medium">
                    No classes assigned today
                  </div>
                ) : (
                  <select
                    value={selectedClass}
                    onChange={(e) => setSelectedClass(e.target.value)}
                    className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] cursor-pointer outline-none focus:border-[var(--blue)]"
                  >
                    {allowedClasses.map(c => (
                      <option key={c} value={c}>Class {c}</option>
                    ))}
                  </select>
                )}
              </div>

              {/* Session selector */}
              <div>
                <label className="block text-[11px] font-medium text-[var(--tx3)] uppercase mb-1.5 flex items-center gap-1">
                  <Clock size={11} /> Session / Attendance Type
                </label>
                <select
                  value={session}
                  onChange={(e) => setSession(e.target.value as any)}
                  className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] cursor-pointer outline-none focus:border-[var(--blue)]"
                >
                  {(isClassTeacherForSelected || isSubstituteFirstPeriodForSelected) && (
                    <option value="first_period">Morning (1st Period - Class Teacher/Substitute)</option>
                  )}
                  {(teachesAfterLunchForSelected || isSubstituteAfterLunchForSelected) && (
                    <option value="lunch_period">Afternoon (1st Period After Lunch - Teacher/Substitute)</option>
                  )}
                  {!(isClassTeacherForSelected || isSubstituteFirstPeriodForSelected) && 
                   !(teachesAfterLunchForSelected || isSubstituteAfterLunchForSelected) && (
                    <option value="">No access for selected class today</option>
                  )}
                </select>
              </div>

              {/* Search */}
              <div className="flex flex-col justify-end">
                <div className="relative w-full">
                  <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[var(--tx3)]" size={12} />
                  <input
                    type="text"
                    placeholder="Search student name/roll..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-8 pr-3 py-2 bg-[var(--surf2)] border border-[var(--b)] rounded-lg text-[12px] text-[var(--tx)] focus:outline-none focus:border-[var(--blue)]"
                  />
                </div>
              </div>
            </div>

            {allowedClasses.length > 0 && 
             !(isClassTeacherForSelected || isSubstituteFirstPeriodForSelected) && 
             !(teachesAfterLunchForSelected || isSubstituteAfterLunchForSelected) && (
              <div className="mt-3 p-3 bg-[var(--amber-bg)] border border-[var(--amber-tx)]/10 text-[var(--amber-tx)] rounded-xl text-[11.5px] flex items-center gap-2">
                <AlertCircle size={13} />
                <span>You do not teach the lunch period slot nor are you the class teacher (or substitute) for Class {selectedClass} on {dayOfWeek}s.</span>
              </div>
            )}
          </Card>

          {allowedClasses.length > 0 && 
           (isClassTeacherForSelected || teachesAfterLunchForSelected || isSubstituteFirstPeriodForSelected || isSubstituteAfterLunchForSelected) && (
            <Card>
              {isLocked && (
                <div className="mb-4 p-3 bg-[var(--teal-bg)]/25 border border-[var(--teal-tx)]/15 rounded-xl flex items-center justify-between gap-3 text-[11.5px] text-[var(--tx)]">
                  <div className="flex items-center gap-2">
                    <CheckCircle size={15} className="text-[var(--teal-tx)]" />
                    <span>✓ Attendance has been submitted and locked for this session.</span>
                  </div>
                  <button
                    type="button"
                    onClick={() => setIsLocked(false)}
                    className="px-2.5 py-1 text-[11px] font-bold bg-[var(--blue-bg)] text-[var(--blue-tx)] rounded-lg hover:bg-[var(--blue-bg)]/80 transition-all cursor-pointer"
                  >
                    Edit / Re-open
                  </button>
                </div>
              )}
              {/* Stats & Bulk Operations */}
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 mb-4 border-b border-[var(--b)] pb-3.5">
                <div className="flex items-center gap-3.5 flex-wrap">
                  <div className="text-[12.5px] font-bold text-[var(--tx)]">
                    Class {selectedClass} Attendance List
                  </div>
                  <div className="flex gap-2">
                    <Badge variant="teal">{presentCount} Present</Badge>
                    <Badge variant="red">{absentCount} Absent</Badge>
                  </div>
                </div>
                <div className="flex gap-2 w-full sm:w-auto">
                  <button
                    onClick={() => markAll('present')}
                    className="flex-1 sm:flex-none px-2.5 py-1.5 text-[11.5px] border border-[var(--b)] bg-[var(--surf2)] text-[var(--tx2)] rounded-lg cursor-pointer hover:border-[var(--blue)] hover:text-[var(--blue-tx)] font-medium transition-all"
                  >
                    Mark All Present
                  </button>
                  <button
                    onClick={() => markAll('absent')}
                    className="flex-1 sm:flex-none px-2.5 py-1.5 text-[11.5px] border border-[var(--b)] bg-[var(--surf2)] text-[var(--tx2)] rounded-lg cursor-pointer hover:border-[var(--red)] hover:text-[var(--red-tx)] font-medium transition-all"
                  >
                    Mark All Absent
                  </button>
                </div>
              </div>

              {/* Students Table */}
              <div className="overflow-x-auto">
                <table className="w-full border-collapse text-[12px] min-w-[500px]">
                  <thead>
                    <tr className="border-b border-[var(--b)] text-[var(--tx3)]">
                      <th className="text-[10.5px] font-medium text-left px-3 py-2 w-12">Init</th>
                      <th className="text-[10.5px] font-medium text-left px-3 py-2">Student Name</th>
                      <th className="text-[10.5px] font-medium text-left px-3 py-2">Roll No</th>
                      <th className="text-[10.5px] font-medium text-center px-3 py-2 w-32">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredStudents.length === 0 ? (
                      <tr>
                        <td colSpan={4} className="text-center py-10 text-[var(--tx3)]">
                          No students found in this class.
                        </td>
                      </tr>
                    ) : (
                      filteredStudents.map((s) => {
                        const isPresent = statusMap[s.id] === 'present';
                        const initials = s.name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
                        return (
                          <tr
                            key={s.id}
                            className="border-b border-[var(--b)] hover:bg-[var(--surf2)]/40 transition-colors last:border-0"
                          >
                            <td className="px-3 py-2.5">
                              <Avatar initials={initials} bg={isPresent ? 'var(--teal-bg)' : 'var(--red-bg)'} color={isPresent ? 'var(--teal-tx)' : 'var(--red-tx)'} />
                            </td>
                            <td className="px-3 py-2.5 font-semibold text-[var(--tx)]">{s.name}</td>
                            <td className="px-3 py-2.5 font-mono text-[11px] text-[var(--tx3)]">{s.roll}</td>
                            <td className="px-3 py-2.5 text-center">
                              <button
                                onClick={() => toggleStudent(s.id)}
                                className={`w-24 py-1.5 rounded-lg text-[11px] font-bold cursor-pointer transition-all flex items-center justify-center gap-1 mx-auto ${
                                  isPresent
                                    ? 'bg-[var(--teal-bg)] text-[var(--teal-tx)] border border-[var(--teal-tx)]/20 hover:opacity-85'
                                    : 'bg-[var(--red-bg)] text-[var(--red-tx)] border border-[var(--red-tx)]/20 hover:opacity-85'
                                }`}
                              >
                                {isPresent ? <Check size={11} /> : <XCircle size={11} />}
                                {isPresent ? 'Present' : 'Absent'}
                              </button>
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>

              {/* Submit Footer */}
              <div className="mt-4 pt-4 border-t border-[var(--b)] flex flex-col sm:flex-row justify-between items-center gap-3">
                <div className="text-[11.5px] text-[var(--tx3)] font-medium">
                  {savedMsg && (
                    <span className="text-[var(--teal-tx)] flex items-center gap-1">
                      <CheckCircle size={13} /> Student Attendance saved and synced successfully!
                    </span>
                  )}
                </div>
                <button
                  onClick={() => setShowConfirmModal(true)}
                  disabled={saving || classStudents.length === 0 || isLocked}
                  className="w-full sm:w-auto flex items-center justify-center gap-2 px-5 py-2.5 bg-[var(--blue)] text-white rounded-xl text-[12.5px] font-bold cursor-pointer hover:opacity-95 disabled:opacity-40 disabled:pointer-events-none transition-all"
                >
                  {saving ? (
                    <Loader2 size={13} className="animate-spin" />
                  ) : (
                    <Save size={13} />
                  )}
                  {saving ? 'Submitting...' : 'Submit Attendance'}
                </button>
              </div>
            </Card>
          )}
        </div>
      )}
      {showConfirmModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-[var(--surf)] border border-[var(--b)] rounded-2xl w-full max-w-[420px] shadow-2xl overflow-hidden">
            {/* Header with gradient */}
            <div className="bg-gradient-to-r from-[var(--purple)] to-[#7c3aed] p-4 text-white flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Users size={16} />
                <span className="text-[13.5px] font-bold">Confirm Attendance Submission</span>
              </div>
              <button 
                onClick={() => setShowConfirmModal(false)}
                className="p-1 hover:bg-white/10 rounded-lg text-white/80 hover:text-white transition-colors cursor-pointer"
              >
                <XCircle size={16} />
              </button>
            </div>

            {/* Body */}
            <div className="p-6 space-y-4">
              <p className="text-xs text-[var(--tx2)]">
                You are about to submit attendance for <strong className="text-[var(--tx)]">Class {selectedClass}</strong> ({session === 'first_period' ? 'Morning' : 'Afternoon'}) on <strong className="text-[var(--tx)]">{date}</strong>.
              </p>

              <div className="grid grid-cols-2 gap-3">
                <div className="bg-[var(--teal-bg)]/30 border border-[var(--teal-tx)]/15 rounded-xl p-3 text-center">
                  <div className="text-[9.5px] text-[var(--teal-tx)] font-semibold uppercase tracking-wider mb-1">Present</div>
                  <div className="text-[20px] font-bold text-[var(--teal-tx)]">{presentCount}</div>
                  <div className="text-[9px] text-[var(--tx3)] mt-0.5">Students</div>
                </div>
                <div className="bg-[var(--red-bg)]/30 border border-[var(--red-tx)]/15 rounded-xl p-3 text-center">
                  <div className="text-[9.5px] text-[var(--red-tx)] font-semibold uppercase tracking-wider mb-1">Absent</div>
                  <div className="text-[20px] font-bold text-[var(--red-tx)]">{absentCount}</div>
                  <div className="text-[9px] text-[var(--tx3)] mt-0.5">Students</div>
                </div>
              </div>

              <div className="bg-[var(--surf2)] border border-[var(--b)] rounded-xl p-3 flex items-start gap-2">
                <AlertCircle size={13} className="text-[var(--blue-tx)] mt-0.5 flex-shrink-0" />
                <p className="text-[10px] text-[var(--tx2)] leading-relaxed">
                  Once submitted, stats will sync to dashboards immediately. Absent notifications will be dispatched if enabled.
                </p>
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-3 p-5 pt-0">
              <button 
                type="button" 
                onClick={() => setShowConfirmModal(false)}
                className="flex-1 py-2.5 border border-[var(--b)] bg-[var(--surf2)] rounded-xl text-[12px] font-medium text-[var(--tx)] hover:bg-[var(--surf3)] cursor-pointer transition-colors"
              >
                Cancel
              </button>
              <button 
                type="button" 
                onClick={() => {
                  setShowConfirmModal(false);
                  handleSubmit();
                }}
                className="flex-1 py-2.5 bg-gradient-to-r from-[var(--purple)] to-[#7c3aed] text-white rounded-xl text-[12px] font-bold hover:opacity-90 cursor-pointer shadow-md transition-all flex items-center justify-center gap-1.5"
              >
                <Save size={12} /> Confirm &amp; Submit
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  Search, Plus, GraduationCap, Phone, Edit2, Trash2, Eye,
  X, Loader2, AlertCircle, CheckCircle2, Download, Mail,
  MapPin, Briefcase, Calendar, Users, Award, ArrowLeft,
  ChevronLeft, ChevronRight,
} from 'lucide-react';
import { Card } from '../components/Card';
import { Badge } from '../components/Badge';
import { KPICard } from '../components/KPICard';
import { api } from '../services/api';
import { formatDate } from '../utils/date';
import { ConfirmDialog } from '../components/ConfirmDialog';
import { EmptyState } from '../components/EmptyState';
import { TableSkeleton } from '../components/Skeleton';
import {
  type LocalAlumni,
  readLocalAlumni,
  addLocalAlumni,
  updateLocalAlumni,
  deleteLocalAlumni,
  mergeAlumni,
} from '../utils/alumniStore';

interface Alumni extends LocalAlumni {}

type ModalType = 'add' | 'view' | 'edit' | null;

const PASS_OUT_YEARS = Array.from({ length: 20 }, (_, i) => String(new Date().getFullYear() - i));

const OCCUPATION_OPTIONS = [
  'Engineering Student',
  'Medical Student',
  'Arts/Science Student',
  'Commerce Student',
  'Software Engineer',
  'Doctor',
  'Lawyer',
  'Teacher',
  'Business / Entrepreneur',
  'Government Job',
  'Other',
];

const GENDER_VARIANTS: Record<string, 'blue' | 'pink' | 'purple'> = {
  Male: 'blue',
  Female: 'pink',
  Other: 'purple',
};

const STATUS_VARIANTS: Record<string, 'teal' | 'amber' | 'gray'> = {
  Verified: 'teal',
  Unverified: 'amber',
  Inactive: 'gray',
};

// ── Helpers ───────────────────────────────────────────────────────────────────
function initials(name: string) {
  return name.split(' ').slice(0, 2).map(w => w[0] ?? '').join('').toUpperCase();
}

const AVATAR_COLORS = [
  { bg: 'var(--blue-bg)', color: 'var(--blue-tx)' },
  { bg: 'var(--teal-bg)', color: 'var(--teal-tx)' },
  { bg: 'var(--purple-bg)', color: 'var(--purple-tx)' },
  { bg: 'var(--amber-bg)', color: 'var(--amber-tx)' },
  { bg: 'var(--coral-bg)', color: 'var(--coral-tx)' },
  { bg: 'var(--green-bg)', color: 'var(--green-tx)' },
];
function avatarColor(id: string) {
  const idx = id.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0) % AVATAR_COLORS.length;
  return AVATAR_COLORS[idx];
}

const ITEMS_PER_PAGE = 10;

// ── Component ─────────────────────────────────────────────────────────────────
export function Alumni() {
  const [alumni, setAlumni] = useState<Alumni[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');

  const [search, setSearch] = useState('');
  const [yearFilter, setYearFilter] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');

  const [modal, setModal] = useState<ModalType>(null);
  const [selected, setSelected] = useState<Alumni | null>(null);
  const [detailAlumni, setDetailAlumni] = useState<Alumni | null>(null);

  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  const [currentPage, setCurrentPage] = useState(1);
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});

  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null);

  // ── Form field state ─────────────────────────────────────────────────────
  const [fname, setFname] = useState('');
  const [lname, setLname] = useState('');
  const [fGender, setFGender] = useState<'Male' | 'Female' | 'Other'>('Male');
  const [fDob, setFDob] = useState('');
  const [fRoll, setFRoll] = useState('');
  const [fYear, setFYear] = useState(PASS_OUT_YEARS[0]);
  const [fClass, setFClass] = useState('10');
  const [fSection, setFSection] = useState('A');
  const [fPhone, setFPhone] = useState('');
  const [fEmail, setFEmail] = useState('');
  const [fAddress, setFAddress] = useState('');
  const [fOccupation, setFOccupation] = useState(OCCUPATION_OPTIONS[0]);
  const [fAchievement, setFAchievement] = useState('');
  const [fStatus, setFStatus] = useState<'Verified' | 'Unverified' | 'Inactive'>('Unverified');

  // ── Toast helper ─────────────────────────────────────────────────────────
  const showToast = (msg: string, ok: boolean) => {
    setToast({ msg, ok });
    setTimeout(() => setToast(null), 4000);
  };

  // ── Load — merges backend + localStorage store ──────────────────────────
  const load = async () => {
    setLoading(true);
    try {
      let backendAlumni: Alumni[] = [];
      try {
        const data = await api.getResources('alumni');
        if (Array.isArray(data) && data.length > 0) {
          backendAlumni = data.map((a: any) => ({
            id: String(a.id),
            name: a.name,
            roll: a.roll || a.enrollment_number || '',
            passOutYear: String(a.pass_out_year || a.passOutYear || ''),
            class: String(a.class || '10'),
            section: a.section || 'A',
            gender: (a.gender as any) || 'Male',
            dob: a.dob ? a.dob.slice(0, 10) : '',
            phone: a.phone || a.student_mobile || '',
            email: a.email || '',
            address: a.address || a.village || '',
            currentOccupation: a.current_occupation || a.currentOccupation || '',
            achievement: a.achievement || '',
            status: a.status === 'verified' ? 'Verified' : a.status === 'inactive' ? 'Inactive' : 'Unverified',
            source: 'backend' as const,
          }));
        }
      } catch {
        // Backend may not have alumni endpoint yet — that's fine
      }

      // Merge backend records with locally-stored ones (from promotion or manual adds)
      const merged = (mergeAlumni(backendAlumni) as Alumni[]).filter(a => a.status !== 'Deleted');

      setAlumni(merged);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);
  useEffect(() => { setCurrentPage(1); }, [search, yearFilter, statusFilter]);

  // ── Populate form on modal open ───────────────────────────────────────────
  useEffect(() => {
    if (modal === 'add') {
      setFname(''); setLname(''); setFGender('Male'); setFDob('');
      setFRoll(''); setFYear(PASS_OUT_YEARS[0]); setFClass('10'); setFSection('A');
      setFPhone(''); setFEmail(''); setFAddress('');
      setFOccupation(OCCUPATION_OPTIONS[0]); setFAchievement(''); setFStatus('Unverified');
      setFormErrors({}); setSaveError('');
    } else if ((modal === 'edit') && selected) {
      const [first, ...rest] = selected.name.split(' ');
      setFname(first); setLname(rest.join(' '));
      setFGender(selected.gender); setFDob(selected.dob);
      setFRoll(selected.roll); setFYear(selected.passOutYear);
      setFClass(selected.class); setFSection(selected.section);
      setFPhone(selected.phone); setFEmail(selected.email);
      setFAddress(selected.address); setFOccupation(selected.currentOccupation);
      setFAchievement(selected.achievement); setFStatus(selected.status === 'Deleted' ? 'Unverified' : selected.status);
      setFormErrors({}); setSaveError('');
    }
  }, [modal, selected]);

  // ── Filtering & pagination ────────────────────────────────────────────────
  const filtered = alumni.filter(a => {
    const q = search.toLowerCase();
    const matchSearch = a.name.toLowerCase().includes(q) ||
      a.roll.toLowerCase().includes(q) ||
      a.currentOccupation.toLowerCase().includes(q) ||
      a.achievement.toLowerCase().includes(q);
    const matchYear = yearFilter === 'All' || a.passOutYear === yearFilter;
    const matchStatus = statusFilter === 'All' || a.status === statusFilter;
    return matchSearch && matchYear && matchStatus;
  });

  const totalPages = Math.max(1, Math.ceil(filtered.length / ITEMS_PER_PAGE));
  const paginated = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  // ── KPIs ─────────────────────────────────────────────────────────────────
  const verifiedCount = alumni.filter(a => a.status === 'Verified').length;
  const uniqueYears = [...new Set(alumni.map(a => a.passOutYear))].length;
  const employedCount = alumni.filter(a =>
    ['Software Engineer', 'Doctor', 'Lawyer', 'Teacher', 'Business / Entrepreneur', 'Government Job'].includes(a.currentOccupation)
  ).length;

  // ── Validate + Save ───────────────────────────────────────────────────────
  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const errors: Record<string, string> = {};
    if (!fname.trim()) errors.fname = 'First name is required';
    if (!lname.trim()) errors.lname = 'Last name is required';
    if (!fPhone || fPhone.replace(/\D/g, '').length !== 10) errors.fPhone = 'Valid 10-digit mobile is required';
    if (fEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fEmail)) errors.fEmail = 'Enter a valid email';
    if (Object.keys(errors).length) { setFormErrors(errors); return; }

    setSaving(true);
    const payload = {
      name: `${fname.trim()} ${lname.trim()}`,
      gender: fGender,
      dob: fDob,
      roll: fRoll,
      pass_out_year: fYear,
      class: fClass,
      section: fSection,
      phone: fPhone,
      email: fEmail,
      address: fAddress,
      current_occupation: fOccupation,
      achievement: fAchievement,
      status: fStatus.toLowerCase(),
    };

    try {
      if (modal === 'add') {
        try {
          await api.createResource('alumni', payload);
        } catch {
          // fallback to local
        }
        const localRecord = { ...payload, passOutYear: fYear, currentOccupation: fOccupation, status: fStatus, source: 'manual' as const };
        const _added = addLocalAlumni(localRecord as any);
        showToast('Alumni record added!', true);
      } else if (modal === 'edit' && selected) {
        try {
          if (selected.source === 'backend' || !selected.id.toString().startsWith('local-')) {
            await api.updateResource('alumni', selected.id, payload);
          }
        } catch {
          // ignore backend failure
        }
        const localRecord = { ...payload, passOutYear: fYear, currentOccupation: fOccupation, status: fStatus, source: selected.source || 'manual' };
        updateLocalAlumni(selected.id, localRecord as any);
        showToast('Alumni record updated!', true);
      }
      setModal(null);
      await load();
    } catch (err) {
      setSaveError(err?.message || 'Failed to save. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  // ── Delete ────────────────────────────────────────────────────────────────
  const confirmDelete = async () => {
    if (!deleteId) return;
    setDeleting(true);
    try {
      if (!deleteId.toString().startsWith('local-')) {
        await api.updateResource('alumni', deleteId, { status: 'Deleted' });
      }
      updateLocalAlumni(deleteId, { status: 'Deleted' as any });
      await load();
      showToast('Alumni record moved to recycle bin.', true);
    } catch {
      // local fallback
      updateLocalAlumni(deleteId, { status: 'Deleted' as any });
      await load();
      showToast('Alumni record moved to recycle bin.', true);
    } finally {
      setDeleting(false);
      setDeleteId(null);
    }
  };

  // ── CSV Export ────────────────────────────────────────────────────────────
  const handleExport = () => {
    const headers = ['Name', 'Roll No', 'Pass-Out Year', 'Class', 'Gender', 'Phone', 'Email', 'Occupation', 'Achievement', 'Status'];
    const rows = filtered.map(a => [
      a.name, a.roll, a.passOutYear, `${a.class}-${a.section}`,
      a.gender, a.phone, a.email, a.currentOccupation, a.achievement, a.status,
    ]);
    const csv = [headers, ...rows].map(r => r.map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `alumni_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click(); URL.revokeObjectURL(url);
  };

  // ── Detail view ───────────────────────────────────────────────────────────
  const renderDetail = () => {
    if (!detailAlumni) return null;
    const a = detailAlumni;
    const av = avatarColor(a.id);
    return (
      <div className="space-y-3">
        {/* Back */}
        <div className="flex items-center justify-between border-b border-[var(--b)] pb-3">
          <div className="flex items-center gap-2.5">
            <button
              onClick={() => setDetailAlumni(null)}
              className="p-1.5 hover:bg-[var(--surf2)] rounded-lg text-[var(--tx2)] hover:text-[var(--tx)] cursor-pointer"
            >
              <ArrowLeft size={14} />
            </button>
            <div>
              <h2 className="text-[13.5px] font-bold text-[var(--tx)]">Alumni Profile</h2>
              <p className="text-[11px] text-[var(--tx3)]">Full details and contact information</p>
            </div>
          </div>
          <button
            onClick={() => { setSelected(a); setDetailAlumni(null); setModal('edit'); }}
            className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] bg-[var(--blue)] text-white rounded-lg hover:opacity-90 cursor-pointer font-medium"
          >
            <Edit2 size={12} /> Edit
          </button>
        </div>

        {/* Avatar + name */}
        <Card className="p-4 flex flex-col sm:flex-row items-center gap-4">
          <div
            className="w-16 h-16 rounded-2xl flex items-center justify-center text-[20px] font-bold flex-shrink-0"
            style={{ background: av.bg, color: av.color }}
          >
            {initials(a.name)}
          </div>
          <div className="flex-1 text-center sm:text-left">
            <div className="text-[16px] font-bold text-[var(--tx)]">{a.name}</div>
            <div className="text-[12px] text-[var(--tx3)] mt-0.5">Roll No: <span className="font-mono">{a.roll || 'N/A'}</span></div>
            <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2 mt-2">
              <Badge variant="blue">Batch of {a.passOutYear}</Badge>
              <Badge variant="blue">Class {a.class}-{a.section}</Badge>
              <Badge variant={STATUS_VARIANTS[a.status] ?? 'gray'}>{a.status}</Badge>
            </div>
          </div>
        </Card>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-3.5">
          {/* Personal Info */}
          <Card className="space-y-3">
            <div className="text-[12.5px] font-bold text-[var(--tx)] pb-2 border-b border-[var(--b)] flex items-center gap-1.5">
              <GraduationCap size={13} className="text-[var(--tx3)]" /> Personal Details
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
              {[
                { label: 'Gender', value: a.gender },
                { label: 'Date of Birth', value: formatDate(a.dob) },
                { label: 'Phone', value: a.phone },
                { label: 'Email', value: a.email || 'N/A' },
              ].map(item => (
                <div key={item.label} className="bg-[var(--surf2)] rounded-xl p-3">
                  <div className="text-[10px] text-[var(--tx3)] mb-0.5">{item.label}</div>
                  <div className="text-[12px] font-semibold text-[var(--tx)]">{item.value || 'N/A'}</div>
                </div>
              ))}
              <div className="bg-[var(--surf2)] rounded-xl p-3 sm:col-span-2">
                <div className="text-[10px] text-[var(--tx3)] mb-0.5 flex items-center gap-1"><MapPin size={10} /> Address</div>
                <div className="text-[12px] font-semibold text-[var(--tx)]">{a.address || 'N/A'}</div>
              </div>
            </div>
          </Card>

          {/* Career / Achievement */}
          <Card className="space-y-3">
            <div className="text-[12.5px] font-bold text-[var(--tx)] pb-2 border-b border-[var(--b)] flex items-center gap-1.5">
              <Briefcase size={13} className="text-[var(--tx3)]" /> Career & Achievement
            </div>
            <div className="space-y-2.5">
              <div className="bg-[var(--surf2)] rounded-xl p-3">
                <div className="text-[10px] text-[var(--tx3)] mb-0.5 flex items-center gap-1"><Briefcase size={10} /> Current Occupation</div>
                <div className="text-[12px] font-semibold text-[var(--tx)]">{a.currentOccupation || 'N/A'}</div>
              </div>
              <div className="bg-[var(--teal-bg)] rounded-xl p-3 border border-[var(--teal-tx)]/15">
                <div className="text-[10px] text-[var(--teal-tx)] mb-0.5 flex items-center gap-1"><Award size={10} /> Achievement / College</div>
                <div className="text-[12px] font-semibold text-[var(--teal-tx)]">{a.achievement || 'N/A'}</div>
              </div>
              <div className="flex gap-2">
                {a.phone && (
                  <a
                    href={`tel:${a.phone}`}
                    className="flex items-center gap-1.5 px-3 py-2 bg-[var(--blue-bg)] text-[var(--blue-tx)] rounded-xl text-[11.5px] font-semibold hover:opacity-90 transition-opacity"
                  >
                    <Phone size={12} /> Call
                  </a>
                )}
                {a.email && (
                  <a
                    href={`mailto:${a.email}`}
                    className="flex items-center gap-1.5 px-3 py-2 bg-[var(--purple-bg)] text-[var(--purple-tx)] rounded-xl text-[11.5px] font-semibold hover:opacity-90 transition-opacity"
                  >
                    <Mail size={12} /> Email
                  </a>
                )}
              </div>
            </div>
          </Card>
        </div>
      </div>
    );
  };

  // ── Add/Edit Modal ────────────────────────────────────────────────────────
  const renderModal = () => {
    if (!modal || modal === 'view') return null;
    const isAdd = modal === 'add';
    const fieldCls = (err?: string) =>
      `w-full bg-[var(--surf2)] border ${err ? 'border-[var(--red-tx)]' : 'border-[var(--b)]'} rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] outline-none focus:border-[var(--blue)] transition-colors`;

    return (
      <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
        <div className="bg-[var(--surf)] border border-[var(--b)] rounded-2xl w-full max-w-[560px] shadow-2xl overflow-hidden max-h-[90vh] flex flex-col">
          {/* Header */}
          <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--b)] flex-shrink-0">
            <div>
              <div className="text-[13.5px] font-bold text-[var(--tx)]">{isAdd ? 'Add Alumni Record' : 'Edit Alumni Record'}</div>
              <div className="text-[11px] text-[var(--tx3)] mt-0.5">{isAdd ? 'Register a former student in the alumni network' : 'Update alumni information'}</div>
            </div>
            <button onClick={() => setModal(null)} className="p-1.5 rounded-lg hover:bg-[var(--surf2)] cursor-pointer text-[var(--tx2)]">
              <X size={16} />
            </button>
          </div>

          {/* Body */}
          <form id="alumni-form" onSubmit={handleSave} className="overflow-y-auto flex-1">
            <div className="p-5 space-y-4">
              {/* Name row */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">First Name *</label>
                  <input value={fname} onChange={e => { setFname(e.target.value); setFormErrors(prev => ({ ...prev, fname: '' })); }}
                    className={fieldCls(formErrors.fname)} placeholder="Arjun" />
                  {formErrors.fname && <p className="text-[10.5px] text-[var(--red-tx)] mt-1">{formErrors.fname}</p>}
                </div>
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Last Name *</label>
                  <input value={lname} onChange={e => { setLname(e.target.value); setFormErrors(prev => ({ ...prev, lname: '' })); }}
                    className={fieldCls(formErrors.lname)} placeholder="Reddy" />
                  {formErrors.lname && <p className="text-[10.5px] text-[var(--red-tx)] mt-1">{formErrors.lname}</p>}
                </div>
              </div>

              {/* Roll + Year */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Roll / Admission No.</label>
                  <input value={fRoll} onChange={e => setFRoll(e.target.value)}
                    className={fieldCls()} placeholder="KTS2022001" />
                </div>
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Pass-Out Year *</label>
                  <select value={fYear} onChange={e => setFYear(e.target.value)} className={fieldCls()}>
                    {PASS_OUT_YEARS.map(y => <option key={y}>{y}</option>)}
                  </select>
                </div>
              </div>

              {/* Class + Section + Gender */}
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Class</label>
                  <select value={fClass} onChange={e => setFClass(e.target.value)} className={fieldCls()}>
                    {['6','7','8','9','10'].map(c => <option key={c}>{c}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Section</label>
                  <select value={fSection} onChange={e => setFSection(e.target.value)} className={fieldCls()}>
                    {['A','B','C','D'].map(s => <option key={s}>{s}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Gender</label>
                  <select value={fGender} onChange={e => setFGender(e.target.value as any)} className={fieldCls()}>
                    <option>Male</option><option>Female</option><option>Other</option>
                  </select>
                </div>
              </div>

              {/* DOB */}
              <div>
                <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Date of Birth</label>
                <input type="date" value={fDob} onChange={e => setFDob(e.target.value)} className={fieldCls()} />
              </div>

              {/* Phone + Email */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Phone *</label>
                  <input value={fPhone} onChange={e => { setFPhone(e.target.value.replace(/\D/g, '').slice(0, 10)); setFormErrors(prev => ({ ...prev, fPhone: '' })); }}
                    className={fieldCls(formErrors.fPhone)} placeholder="9876543210" />
                  {formErrors.fPhone && <p className="text-[10.5px] text-[var(--red-tx)] mt-1">{formErrors.fPhone}</p>}
                </div>
                <div>
                  <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Email</label>
                  <input type="email" value={fEmail} onChange={e => { setFEmail(e.target.value); setFormErrors(prev => ({ ...prev, fEmail: '' })); }}
                    className={fieldCls(formErrors.fEmail)} placeholder="arjun@gmail.com" />
                  {formErrors.fEmail && <p className="text-[10.5px] text-[var(--red-tx)] mt-1">{formErrors.fEmail}</p>}
                </div>
              </div>

              {/* Address */}
              <div>
                <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Address</label>
                <input value={fAddress} onChange={e => setFAddress(e.target.value)}
                  className={fieldCls()} placeholder="City, District, State" />
              </div>

              {/* Occupation */}
              <div>
                <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Current Occupation</label>
                <select value={fOccupation} onChange={e => setFOccupation(e.target.value)} className={fieldCls()}>
                  {OCCUPATION_OPTIONS.map(o => <option key={o}>{o}</option>)}
                </select>
              </div>

              {/* Achievement */}
              <div>
                <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Achievement / College / Employer</label>
                <input value={fAchievement} onChange={e => setFAchievement(e.target.value)}
                  className={fieldCls()} placeholder="e.g. B.Tech at JNTU Hyderabad" />
              </div>

              {/* Status */}
              <div>
                <label className="block text-[11.5px] font-medium text-[var(--tx2)] mb-1.5">Verification Status</label>
                <select value={fStatus} onChange={e => setFStatus(e.target.value as any)} className={fieldCls()}>
                  <option>Unverified</option><option>Verified</option><option>Inactive</option>
                </select>
              </div>

              {saveError && (
                <div className="flex items-center gap-2 text-[11.5px] text-[var(--red-tx)] bg-[var(--red-bg)] p-3 rounded-xl border border-[var(--red-tx)]/20">
                  <AlertCircle size={13} /> {saveError}
                </div>
              )}
            </div>
          </form>

          {/* Footer */}
          <div className="flex gap-2 px-5 py-4 border-t border-[var(--b)] flex-shrink-0">
            <button onClick={() => setModal(null)}
              className="flex-1 py-2.5 border border-[var(--b)] bg-[var(--surf2)] rounded-xl text-[12.5px] text-[var(--tx)] cursor-pointer hover:bg-[var(--surf3)]">
              Cancel
            </button>
            <button form="alumni-form" type="submit" disabled={saving}
              className="flex-1 py-2.5 bg-[var(--blue)] text-white rounded-xl text-[12.5px] font-semibold cursor-pointer hover:opacity-90 flex items-center justify-center gap-1.5 disabled:opacity-60">
              {saving ? <Loader2 size={13} className="animate-spin" /> : null}
              {isAdd ? 'Add Alumni' : 'Save Changes'}
            </button>
          </div>
        </div>
      </div>
    );
  };

  // ── Main render ───────────────────────────────────────────────────────────
  return (
    <div className="flex-1 overflow-y-auto p-3.5 bg-[var(--bg)] relative">

      {/* Toast */}
      {toast && (
        <div className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-xl shadow-xl border text-[12px] font-semibold ${
          toast.ok
            ? 'bg-[var(--teal-bg)] border-[var(--teal-tx)]/20 text-[var(--teal-tx)]'
            : 'bg-[var(--red-bg)] border-[var(--red-tx)]/20 text-[var(--red-tx)]'
        }`}>
          {toast.ok ? <CheckCircle2 size={14} /> : <AlertCircle size={14} />}
          {toast.msg}
        </div>
      )}

      {/* Detail view */}
      {detailAlumni ? (
        <Card>{renderDetail()}</Card>
      ) : (
        <>
          {/* KPI row */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5 mb-3">
            <KPICard label="Total Alumni" value={alumni.length} sub="Registered in network"
              icon={<GraduationCap size={15} />} iconBg="var(--blue-bg)" iconColor="var(--blue-tx)" />
            <KPICard label="Verified" value={verifiedCount} sub="Contact confirmed"
              icon={<CheckCircle2 size={15} />} iconBg="var(--teal-bg)" iconColor="var(--teal-tx)" />
            <KPICard label="Batches" value={uniqueYears} sub="Pass-out years"
              icon={<Calendar size={15} />} iconBg="var(--amber-bg)" iconColor="var(--amber-tx)" />
            <KPICard label="Employed / Working" value={employedCount} sub="Professional careers"
              icon={<Briefcase size={15} />} iconBg="var(--purple-bg)" iconColor="var(--purple-tx)" />
          </div>

          <Card>
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
              <div className="text-[13px] font-semibold text-[var(--tx)] flex items-center gap-2">
                <Users size={14} className="text-[var(--tx3)]" />
                Alumni Directory
                {loading && <Loader2 size={13} className="animate-spin text-[var(--tx3)]" />}
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={handleExport}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] border border-[var(--b)] bg-[var(--surf2)] text-[var(--tx)] rounded-lg hover:bg-[var(--surf3)] cursor-pointer"
                >
                  <Download size={12} /> Export CSV
                </button>
                <button
                  onClick={() => { setSelected(null); setModal('add'); }}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] bg-[var(--blue)] text-white rounded-lg hover:opacity-90 cursor-pointer font-medium"
                >
                  <Plus size={12} /> Add Alumni
                </button>
              </div>
            </div>

            {/* Filters */}
            <div className="flex flex-col sm:flex-row gap-2 mb-4">
              <div className="flex items-center gap-2 flex-1 bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2">
                <Search size={13} className="text-[var(--tx3)]" />
                <input
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  placeholder="Search by name, roll, occupation, achievement..."
                  className="flex-1 bg-transparent text-[12px] text-[var(--tx)] placeholder:text-[var(--tx3)] outline-none"
                />
              </div>
              <select
                value={yearFilter}
                onChange={e => setYearFilter(e.target.value)}
                className="bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] outline-none cursor-pointer"
              >
                <option value="All">All Years</option>
                {PASS_OUT_YEARS.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
              <select
                value={statusFilter}
                onChange={e => setStatusFilter(e.target.value)}
                className="bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] outline-none cursor-pointer"
              >
                <option value="All">All Status</option>
                <option>Verified</option>
                <option>Unverified</option>
                <option>Inactive</option>
              </select>
            </div>

            {/* Table */}
            {loading ? (
              <TableSkeleton rows={6} cols={6} />
            ) : filtered.length === 0 ? (
              <EmptyState
                icon={<GraduationCap size={28} />}
                title="No alumni found"
                description={search || yearFilter !== 'All' || statusFilter !== 'All'
                  ? 'Try adjusting your filters or search term.'
                  : 'Add your first alumni record to get started.'}
                actionLabel={!search && yearFilter === 'All' && statusFilter === 'All' ? 'Add Alumni' : undefined}
                onAction={!search && yearFilter === 'All' && statusFilter === 'All' ? () => { setSelected(null); setModal('add'); } : undefined}
              />
            ) : (
              <>
                <div className="overflow-x-auto -mx-3.5">
                  <table className="w-full border-collapse" style={{ minWidth: 720 }}>
                    <thead>
                      <tr className="border-b border-[var(--b)]">
                        {['Name & Roll', 'Batch', 'Gender', 'Occupation', 'Achievement', 'Status', ''].map(h => (
                          <th key={h} className="text-left text-[11.5px] font-semibold text-[var(--tx2)] px-3.5 py-2.5">{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {paginated.map((a, idx) => {
                        const av = avatarColor(a.id);
                        return (
                          <tr
                            key={a.id}
                            className={`border-b border-[var(--b)] hover:bg-[var(--surf2)] transition-colors group ${idx % 2 === 0 ? '' : 'bg-[var(--surf2)]/30'}`}
                          >
                            {/* Name */}
                            <td className="px-3.5 py-2.5">
                              <div className="flex items-center gap-2.5">
                                <div
                                  className="w-7 h-7 rounded-lg flex items-center justify-center text-[11px] font-bold flex-shrink-0"
                                  style={{ background: av.bg, color: av.color }}
                                >
                                  {initials(a.name)}
                                </div>
                                <div>
                                  <div className="text-[12.5px] font-semibold text-[var(--tx)]">{a.name}</div>
                                  <div className="text-[11px] text-[var(--tx3)] font-mono">{a.roll || '—'}</div>
                                </div>
                              </div>
                            </td>
                            {/* Batch */}
                            <td className="px-3.5 py-2.5">
                              <div className="text-[12px] font-semibold text-[var(--tx)]">{a.passOutYear}</div>
                              <div className="text-[11px] text-[var(--tx3)]">Class {a.class}-{a.section}</div>
                            </td>
                            {/* Gender */}
                            <td className="px-3.5 py-2.5">
                              <Badge variant={GENDER_VARIANTS[a.gender] ?? 'gray'}>{a.gender}</Badge>
                            </td>
                            {/* Occupation */}
                            <td className="px-3.5 py-2.5">
                              <div className="text-[12px] text-[var(--tx)] max-w-[140px] truncate">{a.currentOccupation || '—'}</div>
                            </td>
                            {/* Achievement */}
                            <td className="px-3.5 py-2.5">
                              <div className="text-[12px] text-[var(--tx3)] max-w-[160px] truncate">{a.achievement || '—'}</div>
                            </td>
                            {/* Status */}
                            <td className="px-3.5 py-2.5">
                              <Badge variant={STATUS_VARIANTS[a.status] ?? 'gray'}>{a.status}</Badge>
                            </td>
                            {/* Actions */}
                            <td className="px-3.5 py-2.5">
                              <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button
                                  onClick={() => setDetailAlumni(a)}
                                  title="View"
                                  className="p-1.5 hover:bg-[var(--blue-bg)] hover:text-[var(--blue-tx)] text-[var(--tx3)] rounded-lg transition-colors cursor-pointer"
                                >
                                  <Eye size={13} />
                                </button>
                                <button
                                  onClick={() => { setSelected(a); setModal('edit'); }}
                                  title="Edit"
                                  className="p-1.5 hover:bg-[var(--amber-bg)] hover:text-[var(--amber-tx)] text-[var(--tx3)] rounded-lg transition-colors cursor-pointer"
                                >
                                  <Edit2 size={13} />
                                </button>
                                <button
                                  onClick={() => setDeleteId(a.id)}
                                  title="Delete"
                                  className="p-1.5 hover:bg-[var(--red-bg)] hover:text-[var(--red-tx)] text-[var(--tx3)] rounded-lg transition-colors cursor-pointer"
                                >
                                  <Trash2 size={13} />
                                </button>
                                {a.phone && (
                                  <a
                                    href={`tel:${a.phone}`}
                                    title="Call"
                                    className="p-1.5 hover:bg-[var(--teal-bg)] hover:text-[var(--teal-tx)] text-[var(--tx3)] rounded-lg transition-colors"
                                  >
                                    <Phone size={13} />
                                  </a>
                                )}
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                {/* Pagination */}
                {totalPages > 1 && (
                  <div className="flex items-center justify-between mt-3 pt-3 border-t border-[var(--b)]">
                    <span className="text-[11.5px] text-[var(--tx3)]">
                      Showing {(currentPage - 1) * ITEMS_PER_PAGE + 1}–{Math.min(currentPage * ITEMS_PER_PAGE, filtered.length)} of {filtered.length} alumni
                    </span>
                    <div className="flex items-center gap-1">
                      <button
                        disabled={currentPage === 1}
                        onClick={() => setCurrentPage(p => p - 1)}
                        className="p-1.5 rounded-lg border border-[var(--b)] text-[var(--tx2)] hover:bg-[var(--surf2)] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
                      >
                        <ChevronLeft size={13} />
                      </button>
                      {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
                        const pg = i + 1;
                        return (
                          <button
                            key={pg}
                            onClick={() => setCurrentPage(pg)}
                            className={`w-7 h-7 rounded-lg text-[11.5px] font-medium cursor-pointer transition-colors ${
                              pg === currentPage
                                ? 'bg-[var(--blue)] text-white'
                                : 'text-[var(--tx2)] hover:bg-[var(--surf2)]'
                            }`}
                          >
                            {pg}
                          </button>
                        );
                      })}
                      <button
                        disabled={currentPage === totalPages}
                        onClick={() => setCurrentPage(p => p + 1)}
                        className="p-1.5 rounded-lg border border-[var(--b)] text-[var(--tx2)] hover:bg-[var(--surf2)] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
                      >
                        <ChevronRight size={13} />
                      </button>
                    </div>
                  </div>
                )}
              </>
            )}
          </Card>
        </>
      )}

      {/* Add/Edit Modal */}
      {renderModal()}

      {/* Delete Confirm */}
      <ConfirmDialog
        isOpen={!!deleteId}
        title="Delete Alumni Record"
        message="Are you sure you want to remove this alumni from the network? This action cannot be undone."
        confirmText="Delete"
        isDestructive={true}
        loading={deleting}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from 'recharts';
import {
  CheckCircle, XCircle, BarChart2, AlertTriangle, Search, ArrowLeft, Calendar, BookOpen, Clock, Users, ArrowRight, User, ChevronLeft, ChevronRight, Loader2, Trash2
} from 'lucide-react';
// @ts-ignore
import * as XLSX from 'xlsx';
import { KPICard } from '../components/KPICard';
import { Card, CardHeader } from '../components/Card';
import { Badge } from '../components/Badge';
import { Avatar, ProgressBar } from '../components/ui';
import { api, clearApiCache } from '../services/api';

const monthlyData = [
  { month: 'Jan', pct: 90 },
  { month: 'Feb', pct: 88 },
  { month: 'Mar', pct: 93 },
  { month: 'Apr', pct: 91 },
  { month: 'May', pct: 92 },
];

const tooltipStyle = {
  backgroundColor: 'var(--surf)',
  border: '0.5px solid var(--b2)',
  borderRadius: 8,
  fontSize: 11,
  color: 'var(--tx)',
};

interface Batch {
  id: string;
  name: string;
  class_teacher_name?: string;
  class_teacher_id?: number;
  isMock?: boolean;
}

interface StudentPercentage {
  id: string;
  name: string;
  enrollment_number: string;
  total_classes: number;
  present_classes: number;
  percentage: number;
}

interface AttendanceRecord {
  id: number;
  status: 'present' | 'absent' | 'late' | 'excused';
  attendance_date: string;
  check_in_time?: string;
  subject?: {
    name: string;
  };
  time_slot?: {
    name: string;
    start_time: string;
    end_time: string;
  };
  faculty?: {
    name: string;
  };
}

export function Attendance() {
  const [view, setView] = useState<'cards' | 'class-details' | 'student-details'>('cards');
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Search & Filters
  const [searchQuery, setSearchQuery] = useState('');

  // Drill-down states
  const [selectedBatch, setSelectedBatch] = useState<Batch | null>(null);
  const [studentsList, setStudentsList] = useState<StudentPercentage[]>([]);

  const [selectedStudent, setSelectedStudent] = useState<StudentPercentage | null>(null);
  const [studentAttendance, setStudentAttendance] = useState<AttendanceRecord[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [classGlanceData, setClassGlanceData] = useState<{ cls: string; pct: number; color: string }[]>([]);

  // Calendar states
  const [currentMonth, setCurrentMonth] = useState<Date>(new Date());
  const [attendanceRecords, setAttendanceRecords] = useState<any[]>([]);
  const [loadingAttendance, setLoadingAttendance] = useState(false);
  const [loadingPeriods, setLoadingPeriods] = useState(false);

  const [students, setStudents] = useState<any[]>([]);
  const [todayAttendance, setTodayAttendance] = useState<any[]>([]);

  // Additional states for bulk actions, sorting, and Excel import
  const [selectedStudentIds, setSelectedStudentIds] = useState<string[]>([]);
  const [sortField, setSortField] = useState<'name' | 'enrollment_number' | 'percentage' | ''>('');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
  const [_showExcelImport, _setShowExcelImport] = useState(false);
  const [_excelImportLoading, setExcelImportLoading] = useState(false);

  const saveSettingToDb = async (key: string, value: string) => {
    try {
      const settings = await api.getResources('settings');
      const existing = settings.find((s: any) => s.key === key);
      if (existing) {
        await api.updateResource('settings', existing.id, { key, value });
      } else {
        await api.createResource('settings', { key, value, group: 'general', type: 'json', is_public: false, is_encrypted: false });
      }
    } catch (err) {
      console.error(`Error saving setting ${key} to DB:`, err);
    }
  };

  const handleSort = (field: 'name' | 'enrollment_number' | 'percentage') => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const handleBulkAttendanceUpdate = async (status: 'present' | 'absent') => {
    if (selectedStudentIds.length === 0 || !selectedBatch) return;
    setLoading(true);
    try {
      const local = localStorage.getItem('kts_student_attendance_records');
      const records = local ? JSON.parse(local) as any[] : [];

      selectedStudentIds.forEach((studentId) => {
        // Mark both morning and lunch period
        ['first_period', 'lunch_period'].forEach((session) => {
          const idx = records.findIndex(r =>
            String(r.studentId) === String(studentId) && r.date === selectedDate && r.session === session
          );
          if (idx !== -1) {
            records[idx].status = status;
          } else {
            records.push({
              studentId,
              className: selectedBatch.name,
              date: selectedDate,
              session,
              status,
              markedBy: 'Admin'
            });
          }
        });
      });

      localStorage.setItem('kts_student_attendance_records', JSON.stringify(records));
      setAttendanceRecords(records);
      await saveSettingToDb('kts_student_attendance_records', JSON.stringify(records));
      setSelectedStudentIds([]);

      // Reload batch percentages
      const response = await api.getBatchStudentPercentages(selectedBatch.id);
      if (response.success && response.data) {
        setStudentsList(response.data.students || []);
      }
      alert(`Bulk marked ${status} successfully!`);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleBulkDeleteAttendance = async () => {
    if (selectedStudentIds.length === 0 || !selectedBatch) return;
    if (window.confirm(`Are you sure you want to delete all attendance records on ${selectedDate} for the ${selectedStudentIds.length} selected students?`)) {
      setLoading(true);
      try {
        const local = localStorage.getItem('kts_student_attendance_records');
        if (local) {
          const records = JSON.parse(local) as any[];
          const filteredRecords = records.filter(r =>
            !(selectedStudentIds.includes(String(r.studentId)) && r.date === selectedDate)
          );
          localStorage.setItem('kts_student_attendance_records', JSON.stringify(filteredRecords));
          setAttendanceRecords(filteredRecords);
          await saveSettingToDb('kts_student_attendance_records', JSON.stringify(filteredRecords));
        }
        setSelectedStudentIds([]);
        // Reload batch percentages
        const response = await api.getBatchStudentPercentages(selectedBatch.id);
        if (response.success && response.data) {
          setStudentsList(response.data.students || []);
        }
        alert('Deleted records successfully!');
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
  };

  const exportClassAttendanceToExcel = () => {
    if (!selectedBatch) return;
    const dataToExport = filteredStudents.map(s => ({
      'Student Name': s.name,
      'Enrollment Number': s.enrollment_number,
      'Total Classes': s.total_classes,
      'Present Classes': s.present_classes,
      'Overall Attendance %': s.percentage
    }));

    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, `Attendance Class ${selectedBatch.name}`);
    XLSX.writeFile(wb, `KTS_Attendance_Class_${selectedBatch.name}.xlsx`);
  };

  const handleImportExcelAttendance = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || !e.target.files[0] || !selectedBatch) return;
    const file = e.target.files[0];
    setExcelImportLoading(true);
    try {
      const reader = new FileReader();
      reader.onload = async (evt) => {
        try {
          const bstr = evt.target?.result;
          const wb = XLSX.read(bstr, { type: 'binary' });
          const wsname = wb.SheetNames[0];
          const ws = wb.Sheets[wsname];
          const data = XLSX.utils.sheet_to_json(ws) as any[];

          const local = localStorage.getItem('kts_student_attendance_records');
          const records = local ? JSON.parse(local) as any[] : [];

          let count = 0;
          data.forEach(row => {
            const enrollment = String(row['Enrollment Number'] || row['EnrollmentNumber'] || '').trim();
            const status = String(row['Status'] || 'present').trim().toLowerCase() as any;

            if (enrollment && ['present', 'absent', 'late', 'excused'].includes(status)) {
              const stud = students.find((s: any) => String(s.enrollment_number).trim() === enrollment);
              if (stud) {
                ['first_period', 'lunch_period'].forEach((session) => {
                  const idx = records.findIndex(r =>
                    String(r.studentId) === String(stud.id) && r.date === selectedDate && r.session === session
                  );
                  if (idx !== -1) {
                    records[idx].status = status;
                  } else {
                    records.push({
                      studentId: String(stud.id),
                      className: selectedBatch.name,
                      date: selectedDate,
                      session,
                      status,
                      markedBy: 'Excel Import'
                    });
                  }
                });
                count++;
              }
            }
          });

          localStorage.setItem('kts_student_attendance_records', JSON.stringify(records));
          setAttendanceRecords(records);
          await saveSettingToDb('kts_student_attendance_records', JSON.stringify(records));

          const response = await api.getBatchStudentPercentages(selectedBatch.id);
          if (response.success && response.data) {
            setStudentsList(response.data.students || []);
          }
          alert(`Successfully imported attendance for ${count} students!`);
        } catch (err) {
          console.error(err);
          alert('Failed to parse spreadsheet file rows');
        }
      };
      reader.readAsBinaryString(file);
    } catch (err) {
      alert('Error reading spreadsheet file');
    } finally {
      setExcelImportLoading(false);
    }
  };

  // Load batches on mount
  useEffect(() => {
    async function loadBatches() {
      setLoading(true);
      setError(null);
      try {
        const [batchesData, studentsData, todayAttendanceRes] = await Promise.all([
          api.getResources('batches').catch((err) => {
            console.warn('Failed to fetch batches list:', err);
            return [];
          }),
          api.getResources('students').catch((err) => {
            console.warn('Failed to fetch students list:', err);
            return [];
          }),
          api.getTodayAttendance('students').catch((err) => {
            console.warn('Failed to fetch today\'s attendance stats:', err);
            return { success: false, data: { attendances: [] } };
          })
        ]);

        const todayAttendanceData = todayAttendanceRes?.success && todayAttendanceRes?.data?.attendances
          ? todayAttendanceRes.data.attendances
          : [];

        const parseBatchName = (name: string) => {
          const str = name.toUpperCase().trim();

          const classMatch = str.match(/^(\d+)/) || str.match(/CLASS\s*(\d+)/i);
          const classId = classMatch ? classMatch[1] : '8';

          let sectionLetter = 'A';
          const stdMatch = str.match(/^(\d+)\s*([A-Z])$/i);
          if (stdMatch) {
            sectionLetter = stdMatch[2];
          } else {
            const sectionMatch = str.match(/(?:SECTION|SEC)\s*([A-Z])/i) || str.match(/\s+([A-Z])$/i);
            if (sectionMatch) {
              sectionLetter = sectionMatch[1];
            }
          }

          return { classId, sectionLetter };
        };

        const uniqueBatchesMap: Record<string, Batch> = {};
        const defaultClasses = ['6', '7', '8', '9', '10'];

        (batchesData || []).forEach((b: any) => {
          const { classId, sectionLetter } = parseBatchName(b.name);
          const mappedName = `${classId}${sectionLetter}`;
          const existing = uniqueBatchesMap[mappedName];
          const isExactMatch = b.name.toUpperCase().trim() === mappedName;

          if (!existing || isExactMatch) {
            uniqueBatchesMap[mappedName] = {
              id: String(b.id),
              name: mappedName,
              class_teacher_name: b.class_teacher_name || undefined,
              isMock: false,
            };
          }
        });

        // Add mock sections for default classes if not present
        defaultClasses.forEach((cId) => {
          const hasSectionA = uniqueBatchesMap[`${cId}A`] !== undefined;
          const hasSectionB = uniqueBatchesMap[`${cId}B`] !== undefined;

          if (!hasSectionA && !hasSectionB) {
            uniqueBatchesMap[`${cId}A`] = { id: `mock-${cId}A`, name: `${cId}A`, isMock: true };
            uniqueBatchesMap[`${cId}B`] = { id: `mock-${cId}B`, name: `${cId}B`, isMock: true };
          }
        });

        const sortedBatches = Object.values(uniqueBatchesMap).sort((a, b) => {
          const matchA = a.name.match(/^(\d+)/);
          const matchB = b.name.match(/^(\d+)/);
          const classA = matchA ? parseInt(matchA[1]) : 0;
          const classB = matchB ? parseInt(matchB[1]) : 0;

          if (classA !== classB) {
            return classA - classB;
          }
          return a.name.localeCompare(b.name);
        });

        // Filter students list to include active students only
        const activeStudents = (studentsData || []).filter(
          (s: any) => (s.status || '').toLowerCase() === 'active'
        );

        // Filter today's attendance to only include records for active students
        const activeStudentIds = new Set(activeStudents.map((s: { id: any; }) => String(s.id)));
        const activeTodayAttendance = (todayAttendanceData || []).filter(
          (att: any) => activeStudentIds.has(String(att.student_id))
        );

        setBatches(sortedBatches);
        setStudents(activeStudents);
        setTodayAttendance(activeTodayAttendance);

        // Compute class-wise today's glance data with real analytics using active students only
        const glanceList = defaultClasses.map((cId) => {
          let totalStudents = 0;
          let presentStudents = 0;
          let hasRealData = false;

          const classSections = Object.values(uniqueBatchesMap).filter(
            (b) => b.name.startsWith(cId) && !b.isMock
          );

          classSections.forEach((sec) => {
            const batchStudents = activeStudents.filter(
              (s: any) => String(s.batch_id) === String(sec.id)
            );
            if (batchStudents.length > 0) {
              hasRealData = true;
              totalStudents += batchStudents.length;

              // Avoid double counting and check if student is marked present in any period today
              const presentInBatch = batchStudents.filter((student: { id: any; }) =>
                activeTodayAttendance.some(
                  (att: any) => String(att.student_id) === String(student.id) && ['present', 'late'].includes(att.status)
                )
              ).length;
              presentStudents += presentInBatch;
            }
          });

          let percentage = 0;
          if (hasRealData && totalStudents > 0) {
            percentage = Math.round((presentStudents / totalStudents) * 100);
          } else {
            percentage = 90 + (Number(cId) % 3) * 3;
          }

          const color = percentage >= 90 ? 'var(--teal)' : percentage >= 75 ? 'var(--blue)' : 'var(--amber)';

          return {
            cls: `Class ${cId}`,
            pct: percentage,
            color: color,
          };
        });

        setClassGlanceData(glanceList);

      } catch (err) {
        console.error('Error fetching batches:', err);
        setError(`Failed to load classes: ${(err as Error).message || err.toString()}`);
      } finally {
        setLoading(false);
      }
    }
    loadBatches();
  }, []);

  // Load class student percentages
  const handleClassClick = async (batch: Batch) => {
    setSelectedBatch(batch);
    setSearchQuery('');
    if (batch.isMock || batch.id.startsWith('mock-')) {
      setStudentsList([]);
      setView('class-details');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const response = await api.getBatchStudentPercentages(batch.id);
      if (response.success && response.data) {
        setStudentsList(response.data.students || []);
        setView('class-details');
      } else {
        setError('Failed to retrieve class details.');
      }
    } catch (err) {
      console.error('Error fetching batch percentages:', err);
      clearApiCache('batches');
      setError((err as Error).message || 'Failed to load student attendance percentages.');
    } finally {
      setLoading(false);
    }
  };

  // Load student detailed view
  const handleStudentClick = async (student: StudentPercentage) => {
    setSelectedStudent(student);
    setCurrentMonth(new Date());
    setLoading(true);
    setError(null);
    try {
      const response = await api.getStudentAttendanceForDate(student.id, selectedDate);
      if (response.success && response.data) {
        setStudentAttendance(response.data.attendances || []);
        setView('student-details');
      } else {
        setError('Failed to retrieve student attendance.');
      }
    } catch (err) {
      console.error('Error fetching student attendance:', err);
      setError((err as Error).message || 'Failed to load student detailed attendance.');
    } finally {
      setLoading(false);
    }
  };

  // Fetch kts_student_attendance_records when selectedStudent changes
  useEffect(() => {
    if (selectedStudent && view === 'student-details') {
      setLoadingAttendance(true);
      api.getResources('settings', { key: 'kts_student_attendance_records' })
        .then((res: any) => {
          if (Array.isArray(res) && res.length > 0 && res[0].value) {
            try {
              const parsed = JSON.parse(res[0].value);
              setAttendanceRecords(parsed);
              localStorage.setItem('kts_student_attendance_records', JSON.stringify(parsed));
            } catch (e) {
              console.error('Error parsing kts_student_attendance_records:', e);
              const local = localStorage.getItem('kts_student_attendance_records');
              if (local) setAttendanceRecords(JSON.parse(local));
            }
          } else {
            const local = localStorage.getItem('kts_student_attendance_records');
            if (local) {
              setAttendanceRecords(JSON.parse(local));
            }
          }
        })
        .catch((err: any) => {
          console.error('Error loading attendance settings:', err);
          const local = localStorage.getItem('kts_student_attendance_records');
          if (local) setAttendanceRecords(JSON.parse(local));
        })
        .finally(() => {
          setLoadingAttendance(false);
        });
    } else {
      setAttendanceRecords([]);
    }
  }, [selectedStudent, view]);

  // Reload student attendance when date changes
  useEffect(() => {
    if (selectedStudent && view === 'student-details') {
      async function reloadStudentAttendance() {
        setLoadingPeriods(true);
        setError(null);
        try {
          const response = await api.getStudentAttendanceForDate(selectedStudent!.id, selectedDate);
          if (response.success && response.data) {
            setStudentAttendance(response.data.attendances || []);
          }
        } catch (err) {
          console.error('Error reloading student attendance:', err);
          setError('Failed to update student attendance for selected date.');
        } finally {
          setLoadingPeriods(false);
        }
      }
      reloadStudentAttendance();
    }
  }, [selectedDate, selectedStudent, view]);

  // Filters for classes & students
  const filteredBatches = batches.filter((b) =>
    b.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const filteredStudents = studentsList.filter((s) =>
    s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.enrollment_number.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const sortedFilteredStudents = [...filteredStudents].sort((a, b) => {
    if (!sortField) return 0;
    let valA = a[sortField];
    let valB = b[sortField];

    if (typeof valA === 'string') valA = valA.toLowerCase();
    if (typeof valB === 'string') valB = valB.toLowerCase();

    if (valA < valB) return sortOrder === 'asc' ? -1 : 1;
    if (valA > valB) return sortOrder === 'asc' ? 1 : -1;
    return 0;
  });

  // Status Badge Mapper
  const getStatusBadge = (status: AttendanceRecord['status']) => {
    switch (status) {
      case 'present': return <Badge variant="teal">Present</Badge>;
      case 'absent': return <Badge variant="red">Absent</Badge>;
      case 'late': return <Badge variant="amber">Late</Badge>;
      case 'excused': return <Badge variant="blue">Excused</Badge>;
      default: return <Badge variant="gray">{status}</Badge>;
    }
  };

  // Avatar Initials Helper
  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .substring(0, 2)
      .toUpperCase();
  };

  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();
  const firstDayOfMonth = new Date(year, month, 1);
  const startDayOfWeek = firstDayOfMonth.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const getDayAttendanceInfo = (dateStr: string) => {
    if (!selectedStudent) return null;
    const dayRecords = attendanceRecords.filter(
      r => String(r.studentId) === String(selectedStudent.id) && r.date === dateStr
    );
    if (dayRecords.length === 0) return null;

    const presentCount = dayRecords.filter(r => r.status?.toLowerCase() === 'present' || r.status?.toLowerCase() === 'late').length;
    const absentCount = dayRecords.filter(r => r.status?.toLowerCase() === 'absent').length;

    if (presentCount > 0 && absentCount > 0) {
      return {
        status: 'partial' as const,
        className: 'bg-[var(--purple-bg)] text-[var(--purple-tx)] border-[var(--purple-tx)]/25',
        label: 'Partial',
        details: `${presentCount} P / ${absentCount} A`
      };
    } else if (presentCount > 0) {
      return {
        status: 'present' as const,
        className: 'bg-[var(--green-bg)] text-[var(--green-tx)] border-[var(--green-tx)]/25',
        label: 'Present',
        details: `${presentCount} Present`
      };
    } else if (absentCount > 0) {
      return {
        status: 'absent' as const,
        className: 'bg-[var(--red-bg)] text-[var(--red-tx)] border-[var(--red-tx)]/25',
        label: 'Absent',
        details: `${absentCount} Absent`
      };
    }
    return null;
  };

  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  return (
    <div className="flex-1 overflow-y-auto p-3.5 bg-[var(--bg)] pb-10">
      {/* Top Cards Section */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5 mb-3">
        <KPICard
          label="Present Today"
          value="258"
          sub="Out of 284"
          icon={<CheckCircle size={15} />}
          iconBg="var(--teal-bg)"
          iconColor="var(--teal-tx)"
        />
        <KPICard
          label="Absent Today"
          value="26"
          sub="Alerts sent via WA+SMS"
          icon={<XCircle size={15} />}
          iconBg="var(--red-bg)"
          iconColor="var(--red-tx)"
        />
        <KPICard
          label="Monthly Avg"
          value={<>92<span className="text-[13px] font-normal text-[var(--tx3)]">%</span></>}
          sub="May 2026"
          icon={<BarChart2 size={15} />}
          iconBg="var(--blue-bg)"
          iconColor="var(--blue-tx)"
        />
        <KPICard
          label="Low Attendance"
          value="8"
          sub="Below 75% this month"
          icon={<AlertTriangle size={15} />}
          iconBg="var(--amber-bg)"
          iconColor="var(--amber-tx)"
        />
      </div>

      {error && (
        <div className="mb-3 p-3 bg-[var(--red-bg)] border border-[var(--red)] text-[var(--red-tx)] rounded-xl text-[12px] flex items-center gap-2">
