                      Enter Marks
                    </button>
                  )}
                  {exam.status === 'Results Published' && (
                    <button
                      onClick={(e) => e.stopPropagation()}
                      className="px-2.5 py-1.5 text-[11px] bg-[var(--blue-bg)] text-[var(--blue-tx)] rounded-lg cursor-pointer font-medium"
