                            type="number"
                            value={r.maths}
                            min={0}
                            max={r.maxMarks}
                            onChange={(e) => {
                              const val = Math.min(r.maxMarks, Math.max(0, Number(e.target.value) || 0));
                              setStudentMarks((prev) => {
                                const examPrev = prev[selectedMarksExamId] ?? {};
                                const subPrev = examPrev[selectedMarksSubject] ?? {};
                                return {
                                  ...prev,
                                  [selectedMarksExamId]: {
                                    ...examPrev,
                                    [selectedMarksSubject]: {
                                      ...subPrev,
                                      [r.roll]: val,
                                    },
                                  },
                                };
