            amount: item.amount,
            due_date: dueDate,
            ...(type === 'class' ? { class_name: className } : { student_id: Number(studentId) })
          })
        )
      );
      const targetStudent = students.find(s => String(s.studentId) === String(studentId));
      setShowAssignModal(false);
      setAssignedItems([]);
      await loadFeesData();
      if (type === 'student' && targetStudent) {
