                                        try {
                                          await api.updateResource('student-fees', fee.id, {
                                            paid_amount: 0,
                                            payment_method: null,
                                            remarks: null,
                                          });
                                          loadFeesData();
                                          loadStudentFees(std.studentId);
                                          alert('Payment deleted successfully!');
