        </Card>

        {/* Active Salary Structure Card */}
        <div className="space-y-2.5">
          <Card>
            <div className="text-[13px] font-semibold text-[var(--tx)] mb-3">Active Salary Structure</div>
            <div className="space-y-2.5">
              {salaryDetails.map((detail, idx) => (
