                          </div>
                        </div>
                      )}
                    </div>

                    <div className="bg-[var(--blue-bg)] rounded-xl p-3.5 flex justify-between items-center">
                      <span className="text-[13px] font-bold text-[var(--blue-tx)]">Net In-Hand</span>
                      <span className="text-[18px] font-bold text-[var(--blue-tx)]">₹{netVal.toLocaleString()}</span>
                    </div>
                  </>
                );
              })()}
            </div>

            <div className="p-5 pt-0">
              <button
                onClick={() => setSelectedSlip(null)}
                className="w-full py-2.5 border border-[var(--b)] bg-[var(--surf2)] rounded-xl text-[12.5px] text-[var(--tx)] cursor-pointer"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useApp } from '../context/AppContext';
import { api } from '../services/api';
import { Card } from '../components/Card';
import { KPICard } from '../components/KPICard';
import { Badge } from '../components/Badge';
import { Avatar } from '../components/ui';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Award, TrendingUp, Users, Percent } from 'lucide-react';

const CLASSES = ['6A', '6B', '7A', '7B', '8A', '8B', '9A', '9B', '10A', '10B'];
const SUBJECTS = ['Mathematics', 'Science', 'English', 'Telugu', 'Hindi', 'Social Studies'];



const AVATAR_COLORS: Record<string, { bg: string; color: string }> = {
  PS: { bg: 'var(--teal-bg)', color: 'var(--teal-tx)' },
  AR: { bg: 'var(--blue-bg)', color: 'var(--blue-tx)' },
  AS: { bg: 'var(--purple-bg)', color: 'var(--purple-tx)' },
  VK: { bg: 'var(--amber-bg)', color: 'var(--amber-tx)' },
  MN: { bg: 'var(--coral-bg)', color: 'var(--coral-tx)' },
};

const tooltipStyle = { backgroundColor: 'var(--surf)', border: '0.5px solid var(--b2)', borderRadius: 8, fontSize: 11, color: 'var(--tx)' };

export function Performance() {
  const { user } = useAuth();
  const { timetable } = useApp();
  const isAdmin = user?.role === 'admin';

  // Filters State
  const [selectedClass, setSelectedClass] = useState('8A');
  const [selectedSubject, setSelectedSubject] = useState('Mathematics');

  // Loaded DB data
  const [students, setStudents] = useState<any[]>([]);
  const [exams, setExams] = useState<any[]>([]);
  const [studentMarks, setStudentMarks] = useState<Record<string, Record<string, Record<string, number>>>>({});
  const [classList, setClassList] = useState<string[]>([]);

  useEffect(() => {
    async function loadData() {
      try {
        // Load Students
        const studentsData = await api.getResources('students', { limit: '1000' });
        setStudents(studentsData || []);

        // Load Batches
        const batchesData = await api.getResources('batches');
        if (batchesData && batchesData.length > 0) {
          const names = batchesData.map((b: any) => b.name).sort((a: string, b: string) => {
            const numA = parseInt(a);
            const numB = parseInt(b);
            if (!isNaN(numA) && !isNaN(numB)) {
              if (numA !== numB) return numA - numB;
              return a.localeCompare(b);
            }
            return a.localeCompare(b);
          });
          setClassList(names);
        }

        // Load Exams
        const examsRes = await api.getResources('settings', { key: 'examinations_exams' });
        if (Array.isArray(examsRes) && examsRes.length > 0 && examsRes[0].value) {
          setExams(JSON.parse(examsRes[0].value));
        }

        // Load Student Marks
        const marksRes = await api.getResources('settings', { key: 'kts_student_marks' });
        if (Array.isArray(marksRes) && marksRes.length > 0 && marksRes[0].value) {
          setStudentMarks(JSON.parse(marksRes[0].value));
        }
      } catch (err) {
        console.error('Error loading performance page data:', err);
      }
    }
    loadData();
  }, []);

  // Compute teacher-specific classes and subject from timetable and profile
  const classesFromTimetable = new Set<string>();
  let teacherSubject = user?.subject || '';

  if (timetable) {
    Object.entries(timetable).forEach(([cls, daysObj]: [string, any]) => {
      if (daysObj) {
        Object.values(daysObj).forEach((slots: any) => {
          if (slots) {
            Object.values(slots).forEach((period: any) => {
              if (period && (
                String(period.teacherId) === String(user?.id) || 
                period.teacher?.toLowerCase() === user?.name?.toLowerCase()
              )) {
                classesFromTimetable.add(cls);
                if (period.subject && !teacherSubject) {
                  teacherSubject = period.subject;
                }
              }
            });
          }
        });
      }
    });
  }

  const teacherClasses = Array.from(new Set([...(user?.classes || []), ...classesFromTimetable]));
  const finalClassList = isAdmin ? (classList.length > 0 ? classList : CLASSES) : teacherClasses;
  const finalSubject = isAdmin ? selectedSubject : (teacherSubject || 'Mathematics');

  // Handle default selector values on role validation
  useEffect(() => {
    if (finalClassList.length > 0 && !finalClassList.includes(selectedClass)) {
      setSelectedClass(finalClassList[0]);
    }
    if (!isAdmin && teacherSubject && selectedSubject !== teacherSubject) {
      setSelectedSubject(teacherSubject);
    }
  }, [user, isAdmin, finalClassList, teacherSubject]);

  // Retrieve exams relevant to the subject and class
  const activeExams = exams.filter((e: any) => {
    const isClassMatch = e.class === 'All Classes' || e.class.split(',').map((c: string) => c.trim()).includes(selectedClass);
    return isClassMatch && e.status !== 'Upcoming';
  });

  // Calculate student performance details
  const getStudentPerformance = () => {
    // 1. Filter students of the selected class
    const classStudents = students.filter((s: any) => {
      const studentClass = s.batch?.name || (s.class && s.section ? `${s.class}${s.section}` : s.class || '');
      return studentClass.toUpperCase() === selectedClass.toUpperCase();
    });

    const calculateStudentStats = (name: string, roll: string, init: string) => {
      let totalScore = 0;
      let totalMaxMarks = 0;
      const examScores: Record<string, number> = {};

      activeExams.forEach((exam) => {
        // Map subjects loosely if needed (e.g. Maths -> Mathematics)
        let savedMark = studentMarks[exam.id]?.[finalSubject]?.[roll];
        if (savedMark === undefined && (finalSubject === 'Mathematics' || finalSubject === 'Maths')) {
          savedMark = studentMarks[exam.id]?.[finalSubject === 'Mathematics' ? 'Maths' : 'Mathematics']?.[roll];
        }

        if (savedMark !== undefined) {
          examScores[exam.id] = savedMark;
          totalScore += savedMark;
          totalMaxMarks += exam.maxMarks || 100;
        }
      });

      const average = totalMaxMarks > 0 ? Math.round((totalScore / totalMaxMarks) * 100) : 0;
      return {
        name,
        roll,
        init,
        examScores,
        average,
        hasMarks: totalMaxMarks > 0,
      };
    };

    let calculatedList: any[] = [];

    if (classStudents.length > 0) {
      calculatedList = classStudents.map((s: any, idx: number) => {
        const initials = s.name.trim().split(/\s+/).map((n: string) => n[0]).join('').slice(0, 2).toUpperCase();
        const roll = s.enrollment_number || `${selectedClass}-${String(idx + 1).padStart(3, '0')}`;
        return calculateStudentStats(s.name, roll, initials || 'ST');
      });
    }

    // Rank students by average percentage
    const sorted = [...calculatedList].sort((a, b) => b.average - a.average);
    return sorted.map((student, idx) => ({
      ...student,
      rank: idx + 1,
    }));
  };

  const studentData = getStudentPerformance();

  // Metrics calculations
  const totalStudents = studentData.length;
  const scoredStudents = studentData.filter(s => s.hasMarks);
  const classAvg = scoredStudents.length > 0 ? Math.round(scoredStudents.reduce((sum, s) => sum + s.average, 0) / scoredStudents.length) : 0;
  const highestScore = scoredStudents.length > 0 ? Math.max(...scoredStudents.map(s => s.average)) : 0;
  const passingRate = scoredStudents.length > 0 ? Math.round((scoredStudents.filter(s => s.average >= 35).length / scoredStudents.length) * 100) : 0;

  // Chart data (performance ranges)
  const rangeCounts = { '90-100 (A+)': 0, '75-89 (A)': 0, '60-74 (B)': 0, '50-59 (C)': 0, '<50 (D/F)': 0 };
  scoredStudents.forEach((s) => {
    if (s.average >= 90) rangeCounts['90-100 (A+)']++;
    else if (s.average >= 75) rangeCounts['75-89 (A)']++;
    else if (s.average >= 60) rangeCounts['60-74 (B)']++;
    else if (s.average >= 50) rangeCounts['50-59 (C)']++;
    else rangeCounts['<50 (D/F)']++;
  });

  const chartData = Object.entries(rangeCounts).map(([range, count]) => ({
    range,
    students: count,
  }));

  const getPerformanceBadge = (avg: number) => {
    if (avg >= 90) return { label: 'Excellent', variant: 'purple' as const };
    if (avg >= 75) return { label: 'Good', variant: 'teal' as const };
    if (avg >= 50) return { label: 'Satisfactory', variant: 'blue' as const };
    return { label: 'Needs Help', variant: 'amber' as const };
  };

  return (
    <div className="flex-1 overflow-y-auto p-3.5 bg-[var(--bg)] space-y-3">
      {/* Header filter controls */}
      <div className="flex flex-col sm:flex-row gap-2 justify-between items-start sm:items-center">
        <div>
          <div className="text-[13px] font-semibold text-[var(--tx)]">Student Performance Dashboard</div>
          <div className="text-[11px] text-[var(--tx3)] mt-0.5">
            Subject academic standing, average grades, and class rank distributions
          </div>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          {finalClassList.length === 0 ? (
            <div className="text-[11.5px] text-[var(--red-tx)] bg-[var(--red-bg)] px-3 py-1.5 rounded-lg font-medium">
              No classes assigned.
            </div>
          ) : (
            <select
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-2.5 py-1.5 text-[11.5px] cursor-pointer outline-none text-[var(--tx)] focus:border-[var(--blue)]"
            >
              {finalClassList.map((c) => (
                <option key={c} value={c}>Class {c}</option>
              ))}
            </select>
          )}
          <select
            value={selectedSubject}
            onChange={(e) => setSelectedSubject(e.target.value)}
            disabled={!isAdmin}
            className="bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-2.5 py-1.5 text-[11.5px] cursor-pointer outline-none text-[var(--tx)] focus:border-[var(--blue)] disabled:opacity-75 disabled:cursor-default"
          >
            {isAdmin ? (
              SUBJECTS.map((s) => (
                <option key={s} value={s}>{s}</option>
              ))
            ) : (
              <option value={finalSubject}>{finalSubject}</option>
            )}
          </select>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2.5">
        <KPICard label="Class Average" value={`${classAvg}%`} sub={`Class ${selectedClass} · ${finalSubject}`} icon={<TrendingUp size={15} />} iconBg="var(--blue-bg)" iconColor="var(--blue-tx)" />
        <KPICard label="Highest Score" value={`${highestScore}%`} sub="Top standing" icon={<Award size={15} />} iconBg="var(--purple-bg)" iconColor="var(--purple-tx)" />
        <KPICard label="Passing Rate (>=35%)" value={`${passingRate}%`} sub="Students passing" icon={<Percent size={15} />} iconBg="var(--teal-bg)" iconColor="var(--teal-tx)" />
        <KPICard label="Total Students" value={totalStudents} sub="Enrolled in class" icon={<Users size={15} />} iconBg="var(--amber-bg)" iconColor="var(--amber-tx)" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-[3fr_2fr] gap-2.5">
        {/* Performance rankings list */}
        <Card>
          <div className="flex items-center justify-between mb-3">
            <div className="text-[13px] font-semibold text-[var(--tx)]">Student Rankings & Marks</div>
            <Badge variant="blue">{finalSubject}</Badge>
          </div>
          <div className="overflow-x-auto">
            {studentData.length === 0 ? (
              <div className="text-center py-12 text-[12px] text-[var(--tx3)]">
                No student details found for Class {selectedClass}.
              </div>
            ) : (
              <table className="w-full border-collapse text-[12px] min-w-[650px]">
                <thead>
                  <tr className="border-b border-[var(--b)] text-[var(--tx3)]">
                    <th className="text-[10.5px] font-medium text-left px-2 py-2">Rank</th>
                    <th className="text-[10.5px] font-medium text-left px-2 py-2">Student</th>
                    <th className="text-[10.5px] font-medium text-left px-2 py-2">Roll No</th>
                    {activeExams.map((exam) => (
                      <th key={exam.id} className="text-[10.5px] font-medium text-left px-2 py-2">{exam.name}</th>
                    ))}
                    <th className="text-[10.5px] font-medium text-left px-2 py-2">Avg %</th>
                    <th className="text-[10.5px] font-medium text-left px-2 py-2">Standing</th>
                  </tr>
                </thead>
                <tbody>
                  {studentData.map((student) => {
                    const badge = getPerformanceBadge(student.average);
                    return (
                      <tr key={student.roll} className="border-b border-[var(--b)] hover:bg-[var(--surf2)] last:border-0">
                        <td className="px-2 py-2.5 font-bold text-[var(--tx3)]">#{student.rank}</td>
                        <td className="px-2 py-2.5">
                          <div className="flex items-center gap-2">
                            <Avatar initials={student.init} bg={AVATAR_COLORS[student.init]?.bg ?? 'var(--surf3)'} color={AVATAR_COLORS[student.init]?.color ?? 'var(--tx2)'} />
                            <span className="font-semibold text-[var(--tx)]">{student.name}</span>
                          </div>
                        </td>
                        <td className="px-2 py-2.5 font-mono text-[11px] text-[var(--tx3)]">{student.roll}</td>
                        {activeExams.map((exam) => (
                          <td key={exam.id} className="px-2 py-2.5 text-[var(--tx2)] font-medium">
                            {student.examScores[exam.id] !== undefined ? `${student.examScores[exam.id]}/${exam.maxMarks || 100}` : '-'}
                          </td>
                        ))}
                        <td className="px-2 py-2.5 font-bold text-[var(--tx)]">{student.average}%</td>
                        <td className="px-2 py-2.5">
                          <Badge variant={badge.variant}>{badge.label}</Badge>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        </Card>

        {/* Visual Chart - Ranges Distribution */}
        <div className="space-y-2.5">
          <Card>
            <div className="text-[12.5px] font-semibold text-[var(--tx)] mb-3">Score Ranges Distribution</div>
            <div className="h-[210px]">
              {scoredStudents.length === 0 ? (
                <div className="h-full flex items-center justify-center text-[12px] text-[var(--tx3)]">
                  No distribution statistics available.
                </div>
              ) : (
                <ResponsiveContainer width="100%" height="100%" minWidth={0} minHeight={0}>
                  <BarChart data={chartData} barSize={24} margin={{ top: 10, right: 4, left: -20, bottom: 0 }}>
                    <CartesianGrid vertical={false} stroke="var(--b)" />
                    <XAxis dataKey="range" tick={{ fontSize: 9.5, fill: 'var(--tx3)' }} axisLine={false} tickLine={false} />
                    <YAxis tick={{ fontSize: 9.5, fill: 'var(--tx3)' }} axisLine={false} tickLine={false} allowDecimals={false} />
                    <Tooltip contentStyle={tooltipStyle} formatter={(v: any) => [v, 'Students']} cursor={{ fill: 'var(--surf2)' }} />
                    <Bar dataKey="students" fill="var(--teal)" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              )}
            </div>
          </Card>

          {/* Top Performers list card */}
          <Card>
            <div className="text-[12.5px] font-semibold text-[var(--tx)] mb-3">Top Performers</div>
            <div className="space-y-2">
              {studentData.slice(0, 3).map((st) => (
                <div key={st.roll} className="flex items-center justify-between p-2.5 bg-[var(--surf2)] rounded-xl border border-[var(--b)]">
                  <div className="flex items-center gap-2">
                    <Avatar initials={st.init} bg={AVATAR_COLORS[st.init]?.bg ?? 'var(--purple-bg)'} color={AVATAR_COLORS[st.init]?.color ?? 'var(--purple-tx)'} />
                    <div>
                      <span className="text-[12px] font-bold text-[var(--tx)]">{st.name}</span>
                      <div className="text-[9.5px] text-[var(--tx3)] font-mono">{st.roll}</div>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-[12.5px] font-bold text-[var(--blue-tx)]">{st.average}%</span>
                    <div className="text-[9px] text-[var(--tx3)]">Overall Average</div>
                  </div>
                </div>
              ))}
              {studentData.length === 0 && (
                <div className="text-center py-6 text-[12px] text-[var(--tx3)]">
                  No records.
                </div>
              )}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  GraduationCap, ArrowRight, CheckCircle2,
  AlertCircle, Loader2, Search, UserMinus, UserCheck, HelpCircle
} from 'lucide-react';
import { Card } from '../components/Card';
import { Badge } from '../components/Badge';
import { api } from '../services/api';
import { addLocalAlumni } from '../utils/alumniStore';

interface Student {
  id: string;
  name: string;
  roll: string;
  class: string;
  section: string;
  gender: 'Male' | 'Female';
  status: 'Active' | 'Transferred' | 'Left';
  batchId: string;
}

interface Batch {
  id: string;
  name: string;
  academic_year_id: string;
  academicYearName?: string;
}

type PromotionAction = 'promote' | 'retain' | 'left' | 'alumni';

interface StudentPromotionState {
  student: Student;
  action: PromotionAction;
  targetBatchId: string; // The selected destination batch ID
}

export function Promotion() {
  const [academicYears, setAcademicYears] = useState<{ id: string; name: string }[]>([]);
  const [batches, setBatches] = useState<Batch[]>([]);

  // Selections
  const [sourceAy, setSourceAy] = useState<string>('');
  const [sourceBatch, setSourceBatch] = useState<string>('');
  const [targetAy, setTargetAy] = useState<string>('');
  const [targetBatch, setTargetBatch] = useState<string>('');

  const [students, setStudents] = useState<Student[]>([]);
  const [promotionStates, setPromotionStates] = useState<Record<string, StudentPromotionState>>({});

  // UI States
  const [loading, setLoading] = useState(false);
  const [studentsLoading, setStudentsLoading] = useState(false);
  const [executing, setExecuting] = useState(false);
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // Load Academic Years and Batches
  useEffect(() => {
    async function loadData() {
      setLoading(true);
      try {
        const [ayData, batchesData] = await Promise.all([
          api.getResources('academic-years'),
          api.getResources('batches', { with: 'academicYear' }),
        ]);

        const sortedAys = (ayData || []).map((ay: any) => ({ id: String(ay.id), name: ay.name }));
        setAcademicYears(sortedAys);

        // Find current academic year to set as default source
        const currentAy = ayData?.find((ay: any) => ay.is_current);
        if (currentAy) {
          setSourceAy(String(currentAy.id));
        } else if (sortedAys.length > 0) {
          setSourceAy(sortedAys[0].id);
        }

        // Find if there is a next academic year for target
        if (sortedAys.length > 1) {
          // If current is found, set next one in list as target
          const currentIndex = sortedAys.findIndex((ay: { id: string; name: string }) => ay.id === String(currentAy?.id));
          if (currentIndex !== -1 && currentIndex < sortedAys.length - 1) {
            setTargetAy(sortedAys[currentIndex + 1].id);
          } else {
            setTargetAy(sortedAys[sortedAys.length - 1].id);
          }
        } else if (sortedAys.length > 0) {
          setTargetAy(sortedAys[0].id);
        }

        const mappedBatches = (batchesData || []).map((b: any) => ({
          id: String(b.id),
          name: b.name,
          academic_year_id: String(b.academic_year_id),
          academicYearName: b.academic_year ? b.academic_year.name : 'N/A'
        }));
        setBatches(mappedBatches);
      } catch (e) {
        console.error('Error loading initial data:', e);
        setMessage({ type: 'error', text: 'Failed to load academic years and classes.' });
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  // Filter batches based on academic years
  const sourceBatches = batches.filter(b => b.academic_year_id === sourceAy);
  const targetBatches = batches.filter(b => b.academic_year_id === targetAy);

  // Detect if selected source is a Class-10 batch (name starts with "10")
  const selectedSourceBatch = batches.find(b => b.id === sourceBatch);
  const isClass10 = selectedSourceBatch
    ? /^10(\s*(?:SECTION|SEC)?\s*[A-Z]?)?$/i.test(selectedSourceBatch.name.trim()) || selectedSourceBatch.name.trim().startsWith('10')
    : false;

  // Set default source batch when sourceAy changes
  useEffect(() => {
    if (sourceBatches.length > 0) {
      setSourceBatch(sourceBatches[0].id);
    } else {
      setSourceBatch('');
    }
  }, [sourceAy, batches]);

  // Set default target batch and match logic when targetAy or sourceBatch changes
  useEffect(() => {
    // If Class 10, no target batch needed — students go to Alumni
    if (isClass10) {
      setTargetBatch('');
      return;
    }
    if (sourceBatch && targetBatches.length > 0) {
      const selectedSourceBatch = batches.find(b => b.id === sourceBatch);
      if (selectedSourceBatch) {
        const match = selectedSourceBatch.name.match(/^(\d+)([A-Z])$/i);
        if (match) {
          const currentClass = parseInt(match[1]);
          const currentSection = match[2];
          const nextClassStr = String(currentClass + 1);
          const nextBatchName = `${nextClassStr}${currentSection}`;
          const matchingTarget = targetBatches.find(b => b.name.toLowerCase() === nextBatchName.toLowerCase());
          if (matchingTarget) {
            setTargetBatch(matchingTarget.id);
            return;
          }
        }
      }
      setTargetBatch(targetBatches[0].id);
    } else {
      setTargetBatch('');
    }
  }, [sourceBatch, targetAy, batches, isClass10]);

  // Load students for selected source batch — auto-set action to 'alumni' for Class 10
  useEffect(() => {
    if (!sourceBatch) {
      setStudents([]);
      setPromotionStates({});
      return;
    }

    async function loadStudents() {
      setStudentsLoading(true);
      setMessage(null);
      try {
        // Fetch all students from cache (no params = uses the pre-warmed cached list)
        // then filter client-side by batch_id — this is instant when cached.
        const allStudents = await api.getResources('students');
        const batchStudents = (allStudents || []).filter(
          (s: any) => String(s.batch_id) === String(sourceBatch)
        );
        const mapped = batchStudents.map((s: any) => ({
          id: String(s.id),
          name: s.name,
          roll: s.enrollment_number || 'N/A',
          class: s.class || '8',
          section: s.section || 'A',
          gender: s.gender || 'Male',
          status: s.status === 'active' || s.status === 'Active' ? 'Active' : s.status === 'left' ? 'Left' : 'Transferred',
          batchId: String(s.batch_id),
        }));

        setStudents(mapped);

        const defaultAction: PromotionAction = isClass10 ? 'alumni' : 'promote';
        const initialStates: Record<string, StudentPromotionState> = {};
        mapped.forEach((student: Student) => {
          initialStates[student.id] = {
            student,
            action: defaultAction,
            targetBatchId: isClass10 ? '' : targetBatch
          };
        });
        setPromotionStates(initialStates);
      } catch (e) {
        console.error('Error loading students:', e);
        setMessage({ type: 'error', text: 'Failed to load students in the selected class.' });
      } finally {
        setStudentsLoading(false);
      }
    }
    loadStudents();
  }, [sourceBatch, isClass10]);

  // Update target batch id for all students when targetBatch changes
  useEffect(() => {
    setPromotionStates(prev => {
      const updated = { ...prev };
      Object.keys(updated).forEach(id => {
        if (updated[id].action === 'promote') {
          updated[id].targetBatchId = targetBatch;
        }
      });
      return updated;
    });
  }, [targetBatch]);

  const handleActionChange = (studentId: string, action: PromotionAction) => {
    setPromotionStates(prev => {
      const state = prev[studentId];
      if (!state) return prev;

      let resolvedTarget = targetBatch;
      if (action === 'retain') {
        // Retain: Stays in the same class level under the NEW academic year.
        // Try to find a batch with the same name in target batches.
        const sourceBatchName = batches.find(b => b.id === sourceBatch)?.name;
        const matchingTarget = targetBatches.find(b => b.name === sourceBatchName);
        resolvedTarget = matchingTarget ? matchingTarget.id : targetBatch;
      }

      return {
        ...prev,
        [studentId]: {
          ...state,
          action,
          targetBatchId: action === 'left' ? '' : resolvedTarget
        }
      };
    });
  };

  const handleSelectAll = (action: PromotionAction) => {
    setPromotionStates(prev => {
      const updated = { ...prev };
      Object.keys(updated).forEach(id => {
        let resolvedTarget = targetBatch;
        if (action === 'retain') {
          const sourceBatchName = batches.find(b => b.id === sourceBatch)?.name;
          const matchingTarget = targetBatches.find(b => b.name === sourceBatchName);
          resolvedTarget = matchingTarget ? matchingTarget.id : targetBatch;
        }
        updated[id] = {
          ...updated[id],
          action,
          targetBatchId: action === 'left' ? '' : resolvedTarget
        };
      });
      return updated;
    });
  };

  const executePromotion = async () => {
    if (students.length === 0) return;

    setExecuting(true);
    setMessage(null);
    let successCount = 0;
    let errorCount = 0;

    try {
      const updates = Object.values(promotionStates).map(async (state) => {
        const payload: Record<string, any> = {};

        if (state.action === 'promote') {
          payload.batch_id = state.targetBatchId;
          payload.status = 'active';
        } else if (state.action === 'retain') {
          payload.batch_id = state.targetBatchId;
          payload.status = 'active';
        } else if (state.action === 'left') {
          payload.status = 'left';
        } else if (state.action === 'alumni') {
          // Mark student as left (graduated) and register in alumni network
          payload.status = 'left';
        }

        try {
          await api.updateResource('students', state.student.id, payload);
          // For alumni action: always write to local store + try backend
          if (state.action === 'alumni') {
            // 1. Write to shared localStorage store immediately (primary fallback)
            addLocalAlumni({
              name: state.student.name,
              roll: state.student.roll,
              passOutYear: String(new Date().getFullYear()),
              class: state.student.class,
              section: state.student.section,
              gender: state.student.gender,
              dob: '',
              phone: '',
              email: '',
              address: '',
              currentOccupation: '',
              achievement: '',
              status: 'Unverified',
              source: 'promotion',
            });
            // 2. Also try the backend (best-effort)
            try {
              await api.createResource('alumni', {
                name: state.student.name,
                roll: state.student.roll,
                pass_out_year: String(new Date().getFullYear()),
                class: state.student.class,
                section: state.student.section,
                gender: state.student.gender,
                status: 'unverified',
              });
            } catch {
              // Backend endpoint may not exist yet — local store is the source of truth
            }
          }
          successCount++;
        } catch (err) {
          console.error(`Failed to update student ${state.student.name}:`, err);
          errorCount++;
        }
      });

      await Promise.all(updates);

      const alumniCount = Object.values(promotionStates).filter(s => s.action === 'alumni').length;
      setMessage({
        type: errorCount === 0 ? 'success' : 'error',
        text: `Promotion completed: ${successCount} student(s) updated successfully.${
          alumniCount > 0 ? ` ${alumniCount} student(s) moved to Alumni network.` : ''
        }${errorCount > 0 ? ` ${errorCount} failed.` : ''}`
      });

      // Reload
      const data = await api.getResources('students', { batch_id: sourceBatch, limit: '1000' });
      const mapped = data.map((s: any) => ({
        id: String(s.id),
        name: s.name,
        roll: s.enrollment_number || 'N/A',
        class: s.class || '8',
        section: s.section || 'A',
        gender: s.gender || 'Male',
        status: s.status === 'active' || s.status === 'Active' ? 'Active' : s.status === 'left' ? 'Left' : 'Transferred',
        batchId: String(s.batch_id),
      }));
      setStudents(mapped);
    } catch (e) {
      console.error('Promotion transaction error:', e);
      setMessage({ type: 'error', text: 'A critical error occurred while executing the promotion.' });
    } finally {
      setExecuting(false);
    }
  };

  const filteredStudents = students.filter(s =>
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    s.roll.toLowerCase().includes(search.toLowerCase())
  );

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center bg-[var(--bg)]">
        <Loader2 className="animate-spin text-[var(--blue)]" size={32} />
      </div>
    );
  }

  return (
    <div className="flex-1 overflow-y-auto p-4 bg-[var(--bg)] space-y-4">
      {/* Title */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-[16px] font-bold text-[var(--tx)] flex items-center gap-2">
            <GraduationCap className="text-[var(--blue)]" size={18} />
            Student Promotion Dashboard
          </h1>
          <p className="text-[11.5px] text-[var(--tx3)]">
            Promote students of the present class to the next class level for the upcoming academic year.
          </p>
        </div>
      </div>

      {/* Selectors and Settings */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Source Configuration */}
        <Card className="p-4 space-y-3">
          <div className="flex items-center gap-2 pb-2 border-b border-[var(--b)] text-[12px] font-semibold text-[var(--tx)]">
            <span className="w-5 h-5 rounded-full bg-[var(--blue-bg)] text-[var(--blue-tx)] flex items-center justify-center text-[10px]">1</span>
            Source Class / Batch (Current)
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="block text-[11px] font-medium text-[var(--tx3)] mb-1">Academic Year</label>
              <select
                value={sourceAy}
                onChange={(e) => setSourceAy(e.target.value)}
                className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] cursor-pointer outline-none"
              >
                {academicYears.map(ay => (
                  <option key={ay.id} value={ay.id}>{ay.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-[11px] font-medium text-[var(--tx3)] mb-1">Class & Section</label>
              <select
                value={sourceBatch}
                onChange={(e) => setSourceBatch(e.target.value)}
                disabled={sourceBatches.length === 0}
                className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] cursor-pointer outline-none disabled:opacity-50"
              >
                {sourceBatches.length === 0 ? (
                  <option value="">No classes found</option>
                ) : (
                  sourceBatches.map(b => (
                    <option key={b.id} value={b.id}>Class {b.name}</option>
                  ))
                )}
              </select>
            </div>
          </div>
        </Card>

        {/* Target Configuration */}
        <Card className="p-4 space-y-3">
          <div className="flex items-center gap-2 pb-2 border-b border-[var(--b)] text-[12px] font-semibold text-[var(--tx)]">
            <span className="w-5 h-5 rounded-full bg-[var(--teal-bg)] text-[var(--teal-tx)] flex items-center justify-center text-[10px]">2</span>
            Destination Class / Batch (Next Year)
          </div>

          {isClass10 ? (
            /* ── Alumni destination panel (shown only for Class 10) ── */
            <div className="flex flex-col items-center justify-center gap-3 py-3">
              <div className="w-12 h-12 rounded-2xl bg-[var(--purple-bg)] flex items-center justify-center">
                <GraduationCap size={22} className="text-[var(--purple-tx)]" />
              </div>
              <div className="text-center">
                <div className="text-[13px] font-bold text-[var(--purple-tx)]">Alumni Network</div>
                <div className="text-[11px] text-[var(--tx3)] mt-0.5">
                  Class 10 students graduate and join the Alumni directory.
                </div>
              </div>
              <div className="flex items-center gap-1.5 px-3 py-1.5 bg-[var(--purple-bg)] border border-[var(--purple-tx)]/20 rounded-xl text-[11.5px] font-semibold text-[var(--purple-tx)]">
                <GraduationCap size={13} />
                Graduates → Alumni
              </div>
            </div>
          ) : (
            /* ── Normal destination dropdowns ── */
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] font-medium text-[var(--tx3)] mb-1">Upcoming Year</label>
                <select
                  value={targetAy}
                  onChange={(e) => setTargetAy(e.target.value)}
                  className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] cursor-pointer outline-none"
                >
                  {academicYears.map(ay => (
                    <option key={ay.id} value={ay.id}>{ay.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-[11px] font-medium text-[var(--tx3)] mb-1">Target Class & Section</label>
                <select
                  value={targetBatch}
                  onChange={(e) => setTargetBatch(e.target.value)}
                  disabled={targetBatches.length === 0}
                  className="w-full bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 text-[12px] text-[var(--tx)] cursor-pointer outline-none disabled:opacity-50"
                >
                  {targetBatches.length === 0 ? (
                    <option value="">No target classes found</option>
                  ) : (
                    targetBatches.map(b => (
                      <option key={b.id} value={b.id}>Class {b.name}</option>
                    ))
                  )}
                </select>
              </div>
            </div>
          )}
        </Card>
      </div>

      {/* Info Warning */}
      <div className="bg-[var(--surf2)] border border-[var(--b)] rounded-xl p-3.5 flex items-start gap-2.5 text-[11.5px] text-[var(--tx2)]">
        <HelpCircle size={15} className="text-[var(--blue-tx)] flex-shrink-0 mt-0.5" />
        <div>
          <span className="font-semibold text-[var(--tx)]">Transition Rules:</span>
          <ul className="list-disc pl-4 mt-1 space-y-0.5">
            {isClass10 ? (
              <li><strong>Alumni</strong> graduates the student and registers them in the Alumni network automatically.</li>
            ) : (
              <li><strong>Promote</strong> updates the student to the selected target batch under the upcoming year.</li>
            )}
            <li><strong>Retain</strong> assigns the student to the corresponding class level under the new year (keeps them in the same grade).</li>
            <li><strong>Left</strong> updates the student status to &quot;Left&quot; (for transfers or dropouts). They are excluded from future year lists.</li>
          </ul>
        </div>
      </div>

      {/* Alerts */}
      {message && (
        <div className={`p-3 rounded-xl border flex items-center gap-2.5 text-[12px] ${
          message.type === 'success' ? 'bg-[var(--teal-bg)] border-[var(--teal-tx)]/20 text-[var(--teal-tx)]' : 'bg-[var(--red-bg)] border-[var(--red-tx)]/20 text-[var(--red-tx)]'
        }`}>
          {message.type === 'success' ? <CheckCircle2 size={15} /> : <AlertCircle size={15} />}
          <span>{message.text}</span>
        </div>
      )}

      {/* Student List Checklist */}
      <Card className="p-4">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-4">
          <div className="text-[12.5px] font-bold text-[var(--tx)]">
            Students List ({filteredStudents.length})
          </div>

          <div className="flex flex-wrap items-center gap-2 w-full sm:w-auto">
            {/* Search */}
            <div className="flex items-center gap-2 bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-2.5 py-1.5 flex-1 sm:flex-none min-w-[200px]">
              <Search size={13} className="text-[var(--tx3)]" />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search students..."
                className="bg-transparent text-[11.5px] text-[var(--tx)] outline-none w-full"
              />
            </div>

            {/* Bulk set buttons */}
            {!isClass10 && (
              <button
                onClick={() => handleSelectAll('promote')}
                className="px-2.5 py-1.5 text-[11px] font-medium border border-[var(--b)] rounded-lg text-[var(--tx2)] hover:bg-[var(--surf2)] cursor-pointer"
              >
                All Promote
              </button>
            )}
            <button
              onClick={() => handleSelectAll('retain')}
              className="px-2.5 py-1.5 text-[11px] font-medium border border-[var(--b)] rounded-lg text-[var(--tx2)] hover:bg-[var(--surf2)] cursor-pointer"
            >
              All Retain
            </button>
            <button
              onClick={() => handleSelectAll('left')}
              className="px-2.5 py-1.5 text-[11px] font-medium border border-[var(--b)] rounded-lg text-[var(--tx2)] hover:bg-[var(--surf2)] cursor-pointer"
            >
              All Left
            </button>
          </div>
        </div>

        {/* Table list */}
        {studentsLoading ? (
          <div className="py-8 flex items-center justify-center">
            <Loader2 className="animate-spin text-[var(--tx3)]" size={24} />
          </div>
        ) : students.length === 0 ? (
          <div className="py-8 text-center text-[12px] text-[var(--tx3)]">
            No active students found in this source class.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full border-collapse text-[12px]">
              <thead>
                <tr className="border-b border-[var(--b)] text-[var(--tx3)] text-left">
                  <th className="py-2 px-1 font-semibold text-[10.5px]">Student Details</th>
                  <th className="py-2 px-1 font-semibold text-[10.5px]">Roll No</th>
                  <th className="py-2 px-1 font-semibold text-[10.5px] text-center">Status</th>
                  <th className="py-2 px-1 font-semibold text-[10.5px] text-right">Transition Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredStudents.map((student) => {
                  const state = promotionStates[student.id];
                  if (!state) return null;

                  return (
                    <tr key={student.id} className="border-b border-[var(--b)] last:border-0 hover:bg-[var(--surf2)] transition-colors">
                      <td className="py-2.5 px-1 font-medium text-[var(--tx)]">
                        {student.name}
                        <span className="text-[10px] text-[var(--tx3)] ml-2">({student.gender})</span>
                      </td>
                      <td className="py-2.5 px-1 font-mono text-[var(--tx2)]">{student.roll}</td>
                      <td className="py-2.5 px-1 text-center">
                        <Badge variant="green">{student.status}</Badge>
                      </td>
                      <td className="py-2.5 px-1 text-right">
                        <div className="inline-flex gap-1 bg-[var(--surf3)] border border-[var(--b)] p-0.5 rounded-lg">
                          {isClass10 ? (
                            /* Class 10: Alumni | Retain | Left */
                            <button
                              onClick={() => handleActionChange(student.id, 'alumni')}
                              className={`px-2.5 py-1 text-[11px] font-semibold rounded-md flex items-center gap-1 cursor-pointer transition-all ${
                                state.action === 'alumni'
                                  ? 'bg-[var(--purple)] text-white shadow'
                                  : 'text-[var(--tx2)] hover:text-[var(--tx)]'
                              }`}
                            >
                              <GraduationCap size={11} /> Alumni
                            </button>
                          ) : (
                            /* Normal classes: Promote */
                            <button
                              onClick={() => handleActionChange(student.id, 'promote')}
                              className={`px-2.5 py-1 text-[11px] font-semibold rounded-md flex items-center gap-1 cursor-pointer transition-all ${
                                state.action === 'promote'
                                  ? 'bg-[var(--blue)] text-white shadow'
                                  : 'text-[var(--tx2)] hover:text-[var(--tx)]'
                              }`}
                            >
                              <UserCheck size={11} /> Promote
                            </button>
                          )}
                          <button
                            onClick={() => handleActionChange(student.id, 'retain')}
                            className={`px-2.5 py-1 text-[11px] font-semibold rounded-md flex items-center gap-1 cursor-pointer transition-all ${
                              state.action === 'retain'
                                ? 'bg-[var(--amber-bg)] text-[var(--amber-tx)] shadow'
                                : 'text-[var(--tx2)] hover:text-[var(--tx)]'
                            }`}
                          >
                            Retain
                          </button>
                          <button
                            onClick={() => handleActionChange(student.id, 'left')}
                            className={`px-2.5 py-1 text-[11px] font-semibold rounded-md flex items-center gap-1 cursor-pointer transition-all ${
                              state.action === 'left'
                                ? 'bg-[var(--red-bg)] text-[var(--red-tx)] shadow'
                                : 'text-[var(--tx2)] hover:text-[var(--tx)]'
                            }`}
                          >
                            <UserMinus size={11} /> Left
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* Footer Execution */}
        {students.length > 0 && (
          <div className="mt-4 pt-4 border-t border-[var(--b)] flex justify-end">
            <button
              onClick={executePromotion}
              disabled={executing || (!isClass10 && targetBatches.length === 0)}
              className="px-4 py-2 bg-[var(--blue)] text-white text-[12px] font-bold rounded-lg flex items-center gap-1.5 hover:opacity-90 disabled:opacity-50 cursor-pointer shadow-sm"
            >
              {executing ? (
                <>
                  <Loader2 className="animate-spin" size={13} />
                  Executing Transition...
                </>
              ) : isClass10 ? (
                <>
                  <GraduationCap size={13} />
                  Graduate to Alumni ({students.length} students)
                </>
              ) : (
                <>
                  <ArrowRight size={13} />
                  Execute Promotion ({students.length} students)
                </>
              )}
            </button>
          </div>
        )}
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  Trash2, RotateCcw, AlertTriangle, Users, BadgeIcon,
  Search, Loader2, RefreshCw, X, GraduationCap, CheckCircle2,
  Activity,
} from 'lucide-react';
import { Card } from '../components/Card';
import { Badge } from '../components/Badge';
import { KPICard } from '../components/KPICard';
import { api } from '../services/api';

interface DeletedStudent {
  id: string;
  name: string;
  roll: string;
  class: string;
  section: string;
  gender: string;
  parent: string;
  phone: string;
  deletedAt?: string;
  isAlumni?: boolean;
}

interface DeletedStaff {
  id: string;
  name: string;
  designation: string;
  department: string;
  category: string;
  phone: string;
  email: string;
  joinDate: string;
}

type Tab = 'students' | 'staff' | 'activity_logs';
type ConfirmAction = { 
  type: 'restore' | 'delete'; 
  entity: 'student' | 'staff' | 'activity_log'; 
  id: string; 
  name: string; 
  isAlumni?: boolean 
} | null;

export function RecycleBin() {
  const [activeTab, setActiveTab] = useState<Tab>('students');
  const [search, setSearch] = useState('');

  // Students
  const [deletedStudents, setDeletedStudents] = useState<DeletedStudent[]>([]);
  const [loadingStudents, setLoadingStudents] = useState(false);

  // Staff
  const [deletedStaff, setDeletedStaff] = useState<DeletedStaff[]>([]);
  const [loadingStaff, setLoadingStaff] = useState(false);

  // Activity Logs
  const [deletedActivityLogs, setDeletedActivityLogs] = useState<any[]>([]);
  const [loadingActivityLogs, setLoadingActivityLogs] = useState(false);
  const [activityExpandedId, setActivityExpandedId] = useState<string | null>(null);

  // Action states
  const [confirm, setConfirm] = useState<ConfirmAction>(null);
  const [processing, setProcessing] = useState(false);
  const [toast, setToast] = useState<{ message: string; success: boolean } | null>(null);

  const showToast = (message: string, success: boolean) => {
    setToast({ message, success });
    setTimeout(() => setToast(null), 3500);
  };

  // ── Load deleted students ──────────────────────────────────────────────
  const loadDeletedStudents = async () => {
    setLoadingStudents(true);
    try {
      const data = await api.getResources('students', { with: 'batch.academicYear', limit: '1000' });
      const left = data
        .filter((s: any) => {
          const status = (s.status || '').toLowerCase();
          return status === 'left' || status === 'dropout';
        })
        .map((s: any) => ({
          id: String(s.id),
          name: s.name,
          roll: s.enrollment_number || 'N/A',
          class: s.class || '—',
          section: s.section || '—',
          gender: s.gender || 'N/A',
          parent: s.father_name || 'N/A',
          phone: s.student_mobile || '—',
          isAlumni: false,
        }));

      let backendAlumni: any[] = [];
      try { backendAlumni = await api.getResources('alumni') || []; } catch {}
      const localAlumniStr = localStorage.getItem('kts_alumni_records');
      const localAlumni = localAlumniStr ? JSON.parse(localAlumniStr) : [];

      const allAlumniMap = new Map();
      [...backendAlumni, ...localAlumni].forEach(a => {
        if (!allAlumniMap.has(String(a.id))) allAlumniMap.set(String(a.id), a);
      });
      const deletedAlumniList = Array.from(allAlumniMap.values())
        .filter((a: any) => (a.status || '').toLowerCase() === 'deleted')
        .map((a: any) => ({
          id: String(a.id),
          name: a.name,
          roll: a.roll || a.enrollment_number || 'N/A',
          class: a.class || '—',
          section: a.section || '—',
          gender: a.gender || 'N/A',
          parent: '—',
          phone: a.phone || '—',
          isAlumni: true,
        }));

      setDeletedStudents([...left, ...deletedAlumniList]);
    } catch (err) {
      console.error('Error loading deleted students:', err);
    } finally {
      setLoadingStudents(false);
    }
  };

  // ── Load deleted staff ─────────────────────────────────────────────────
  const loadDeletedStaff = () => {
    setLoadingStaff(true);
    try {
      const saved = localStorage.getItem('kts_staff_members');
      const all = saved ? JSON.parse(saved) : [];
      const resigned = all.filter((s: any) => s.status === 'Resigned');
      setDeletedStaff(resigned);
    } catch (err) {
      console.error('Error loading deleted staff:', err);
    } finally {
      setLoadingStaff(false);
    }
  };

  // ── Load recycled activity logs ───────────────────────────────────────
  const loadDeletedActivityLogs = async () => {
    setLoadingActivityLogs(true);
    try {
      const res = await api.getActivityLogs({ recycled: 'true', limit: '500' });
      const data = res.data ?? res ?? [];
      setDeletedActivityLogs(data);
    } catch (err) {
      console.error('Error loading recycled activity logs:', err);
    } finally {
      setLoadingActivityLogs(false);
    }
  };

  useEffect(() => {
    loadDeletedStudents();
    loadDeletedStaff();
    loadDeletedActivityLogs();
  }, []);

  const refreshAll = () => {
    if (activeTab === 'students') loadDeletedStudents();
    else if (activeTab === 'staff') loadDeletedStaff();
    else if (activeTab === 'activity_logs') loadDeletedActivityLogs();
  };

  // ── Restore student ────────────────────────────────────────────────────
  const restoreStudent = async (id: string, isAlumni?: boolean) => {
    setProcessing(true);
    try {
      if (isAlumni) {
        if (!id.startsWith('local-')) {
          try { await api.updateResource('alumni', id, { status: 'Unverified' }); } catch {}
        }
        const saved = localStorage.getItem('kts_alumni_records');
        if (saved) {
           const all = JSON.parse(saved);
           const updated = all.map((a: any) => String(a.id) === id ? { ...a, status: 'Unverified' } : a);
           localStorage.setItem('kts_alumni_records', JSON.stringify(updated));
        }
      } else {
        await api.updateResource('students', id, { status: 'active' });
      }
      await loadDeletedStudents();
      showToast(isAlumni ? 'Alumni restored successfully!' : 'Student restored successfully!', true);
    } catch (err) {
      console.error('Error restoring student:', err);
      showToast('Failed to restore student. Please try again.', false);
    } finally {
      setProcessing(false);
      setConfirm(null);
    }
  };

  // ── Permanently delete student ─────────────────────────────────────────
  const permanentDeleteStudent = async (id: string, isAlumni?: boolean) => {
    setProcessing(true);
    try {
      if (isAlumni) {
        if (!id.startsWith('local-')) {
          try { await api.deleteResource('alumni', id); } catch {}
        }
        const saved = localStorage.getItem('kts_alumni_records');
        if (saved) {
           const all = JSON.parse(saved);
           const updated = all.filter((a: any) => String(a.id) !== id);
           localStorage.setItem('kts_alumni_records', JSON.stringify(updated));
        }
      } else {
        await api.deleteResource('students', id);
      }
      await loadDeletedStudents();
      showToast(isAlumni ? 'Alumni permanently deleted.' : 'Student permanently deleted.', true);
    } catch (err) {
      console.error('Error permanently deleting student:', err);
      showToast('Failed to delete student. Please try again.', false);
    } finally {
      setProcessing(false);
      setConfirm(null);
    }
  };

  // ── Restore staff ──────────────────────────────────────────────────────
  const restoreStaff = (id: string) => {
    setProcessing(true);
    try {
      const saved = localStorage.getItem('kts_staff_members');
      const all = saved ? JSON.parse(saved) : [];
      const updated = all.map((s: any) =>
        s.id === id ? { ...s, status: 'Active' } : s
      );
      localStorage.setItem('kts_staff_members', JSON.stringify(updated));
      loadDeletedStaff();
      showToast('Staff member restored successfully!', true);
    } catch (err) {
      console.error('Error restoring staff:', err);
      showToast('Failed to restore staff member.', false);
    } finally {
      setProcessing(false);
      setConfirm(null);
    }
  };

  // ── Permanently delete staff ───────────────────────────────────────────
  const permanentDeleteStaff = (id: string) => {
    setProcessing(true);
    try {
      const saved = localStorage.getItem('kts_staff_members');
      const all = saved ? JSON.parse(saved) : [];
      const updated = all.filter((s: any) => s.id !== id);
      localStorage.setItem('kts_staff_members', JSON.stringify(updated));
      loadDeletedStaff();
      showToast('Staff member permanently deleted.', true);
    } catch (err) {
      console.error('Error permanently deleting staff:', err);
      showToast('Failed to delete staff member.', false);
    } finally {
      setProcessing(false);
      setConfirm(null);
    }
  };

  const isRestorableLog = (log: any) => {
    if (!log.properties || !log.properties.original_created_at) {
      return false;
    }
    const originalDate = new Date(log.properties.original_created_at);
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    return originalDate >= thirtyDaysAgo;
  };

  // ── Restore Activity Log ───────────────────────────────────────────────
  const restoreActivityLog = async (id: string) => {
    setProcessing(true);
    try {
      await api.restoreActivityLog(id);
      await loadDeletedActivityLogs();
      showToast('Activity log restored successfully!', true);
    } catch (err) {
      console.error('Error restoring activity log:', err);
      const errMsg = (err as any).error || (err as Error).message || 'Failed to restore activity log.';
      showToast(errMsg, false);
      alert(errMsg);
    } finally {
      setProcessing(false);
      setConfirm(null);
    }
  };

  // ── Permanently Delete Activity Log ────────────────────────────────────
  const permanentDeleteActivityLog = async (id: string) => {
    setProcessing(true);
    try {
      await api.deleteActivityLog(id);
      await loadDeletedActivityLogs();
      showToast('Activity log permanently deleted.', true);
    } catch (err) {
      console.error('Error permanently deleting activity log:', err);
      showToast('Failed to delete activity log.', false);
    } finally {
      setProcessing(false);
      setConfirm(null);
    }
  };

  // ── Confirm action dispatcher ──────────────────────────────────────────
  const handleConfirm = () => {
    if (!confirm) return;
    if (confirm.type === 'restore' && confirm.entity === 'student') restoreStudent(confirm.id, confirm.isAlumni);
    else if (confirm.type === 'delete' && confirm.entity === 'student') permanentDeleteStudent(confirm.id, confirm.isAlumni);
    else if (confirm.type === 'restore' && confirm.entity === 'staff') restoreStaff(confirm.id);
    else if (confirm.type === 'delete' && confirm.entity === 'staff') permanentDeleteStaff(confirm.id);
    else if (confirm.type === 'restore' && confirm.entity === 'activity_log') restoreActivityLog(confirm.id);
    else if (confirm.type === 'delete' && confirm.entity === 'activity_log') permanentDeleteActivityLog(confirm.id);
  };

  // ── Filtered lists ─────────────────────────────────────────────────────
  const filteredStudents = deletedStudents.filter(s =>
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    s.roll.toLowerCase().includes(search.toLowerCase()) ||
    s.parent.toLowerCase().includes(search.toLowerCase())
  );

  const filteredStaff = deletedStaff.filter(s =>
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    s.designation.toLowerCase().includes(search.toLowerCase()) ||
    s.department.toLowerCase().includes(search.toLowerCase())
  );

  const filteredActivityLogs = deletedActivityLogs.filter(l =>
    l.description.toLowerCase().includes(search.toLowerCase()) ||
    (l.causer_name || '').toLowerCase().includes(search.toLowerCase()) ||
    (l.event || '').toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="flex-1 overflow-y-auto p-3.5 bg-[var(--bg)]">
      {/* Toast notification */}
      {toast && (
        <div className={`fixed top-4 right-4 z-[100] flex items-center gap-2.5 px-4 py-3 rounded-xl shadow-xl border text-[12px] font-semibold animate-fade-in ${
          toast.success
            ? 'bg-[var(--teal-bg)] border-[var(--teal-tx)]/20 text-[var(--teal-tx)]'
            : 'bg-[var(--red-bg)] border-[var(--red-tx)]/20 text-[var(--red-tx)]'
        }`}>
          {toast.success ? <CheckCircle2 size={14} /> : <AlertTriangle size={14} />}
          {toast.message}
        </div>
      )}

      {/* Confirm dialog */}
      {confirm && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-[var(--surf)] border border-[var(--b)] rounded-2xl w-full max-w-[420px] shadow-2xl overflow-hidden">
            <div className={`p-5 pb-4 border-b border-[var(--b)] flex items-start gap-3 ${
              confirm.type === 'delete' ? 'bg-[var(--red-bg)]' : 'bg-[var(--teal-bg)]'
            }`}>
              <div className={`p-2 rounded-xl flex-shrink-0 ${confirm.type === 'delete' ? 'bg-[var(--red-tx)]/10' : 'bg-[var(--teal-tx)]/10'}`}>
                {confirm.type === 'delete'
                  ? <AlertTriangle size={18} className="text-[var(--red-tx)]" />
                  : <RotateCcw size={18} className="text-[var(--teal-tx)]" />
                }
              </div>
              <div>
                <div className="text-[13.5px] font-bold text-[var(--tx)]">
                  {confirm.type === 'restore' ? 'Restore Record' : 'Permanently Delete'}
                </div>
                <div className="text-[11px] text-[var(--tx3)] mt-0.5">
                  {confirm.type === 'restore'
                    ? `Restore "${confirm.name}" back to active records?`
                    : `This will permanently remove "${confirm.name}" and cannot be undone.`
                  }
                </div>
              </div>
            </div>
            <div className="p-4 flex gap-2.5 justify-end">
              <button
                onClick={() => setConfirm(null)}
                disabled={processing}
                className="px-4 py-2 text-[12px] border border-[var(--b)] bg-[var(--surf2)] rounded-lg text-[var(--tx)] hover:bg-[var(--surf3)] cursor-pointer font-medium disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirm}
                disabled={processing}
                className={`px-4 py-2 text-[12px] rounded-lg text-white font-semibold cursor-pointer disabled:opacity-60 flex items-center gap-2 ${
                  confirm.type === 'delete' ? 'bg-[var(--red)]' : 'bg-[var(--teal)]'
                }`}
              >
                {processing && <Loader2 size={12} className="animate-spin" />}
                {confirm.type === 'restore' ? 'Restore' : 'Delete Permanently'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* KPI row */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-2.5 mb-3">
        <KPICard
          label="Deleted Students"
          value={deletedStudents.length}
          sub="Marked as 'Left' in system"
          icon={<GraduationCap size={15} />}
          iconBg="var(--red-bg)"
          iconColor="var(--red-tx)"
        />
        <KPICard
          label="Deleted Staff"
          value={deletedStaff.length}
          sub="Marked as 'Resigned' in system"
          icon={<Users size={15} />}
          iconBg="var(--amber-bg)"
          iconColor="var(--amber-tx)"
        />
        <KPICard
          label="Recycled Activity Logs"
          value={deletedActivityLogs.length}
          sub="Logs 30 to 60 days old"
          icon={<Activity size={15} />}
          iconBg="var(--blue-bg)"
          iconColor="var(--blue-tx)"
        />
        <KPICard
          label="Total Items"
          value={deletedStudents.length + deletedStaff.length + deletedActivityLogs.length}
          sub="Records in recycle bin"
          icon={<Trash2 size={15} />}
          iconBg="var(--purple-bg)"
          iconColor="var(--purple-tx)"
        />
      </div>

      <Card>
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-xl bg-[var(--red-bg)] flex items-center justify-center">
              <Trash2 size={14} className="text-[var(--red-tx)]" />
            </div>
            <div>
              <div className="text-[13px] font-bold text-[var(--tx)]">Recycle Bin</div>
              <div className="text-[10.5px] text-[var(--tx3)]">Restore or permanently delete soft-deleted records</div>
            </div>
          </div>
          <button
            onClick={refreshAll}
            className="flex items-center gap-1.5 px-3 py-1.5 text-[12px] border border-[var(--b)] bg-[var(--surf2)] rounded-lg text-[var(--tx)] hover:bg-[var(--surf3)] cursor-pointer"
            title="Refresh"
          >
            <RefreshCw size={12} /> Refresh
          </button>
        </div>

        {/* Info banner */}
        <div className="mb-4 flex items-start gap-2.5 px-3.5 py-3 bg-[var(--amber-bg)] border border-[var(--amber-tx)]/20 rounded-xl text-[11.5px] text-[var(--amber-tx)]">
          <AlertTriangle size={14} className="flex-shrink-0 mt-0.5" />
          <span>
            {activeTab === 'activity_logs' ? (
              <>
                Activity logs here are between <strong>30 and 60 days old</strong> and have been automatically archived to the Recycle Bin.
                Logs older than 60 days are permanently deleted automatically.
              </>
            ) : (
              <>
                Records here are <strong>soft-deleted</strong> — they remain in the database with a "Left" or "Resigned" status.
                You can restore them at any time, or permanently remove them. Permanent deletion cannot be undone.
              </>
            )}
          </span>
        </div>

        {/* Tabs + Search */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
          <div className="flex border-b border-[var(--b)] overflow-x-auto">
            {([
              { id: 'students' as Tab, label: 'Students', icon: <GraduationCap size={13} />, count: deletedStudents.length },
              { id: 'staff' as Tab, label: 'Staff', icon: <Users size={13} />, count: deletedStaff.length },
              { id: 'activity_logs' as Tab, label: 'Activity Logs', icon: <Activity size={13} />, count: deletedActivityLogs.length },
            ] as const).map(tab => (
              <button
                key={tab.id}
                onClick={() => { setActiveTab(tab.id); setSearch(''); }}
                className={`flex items-center gap-1.5 py-2.5 px-4 text-[12px] font-semibold border-b-2 whitespace-nowrap transition-all cursor-pointer ${
                  activeTab === tab.id
                    ? 'border-[var(--blue)] text-[var(--blue-tx)]'
                    : 'border-transparent text-[var(--tx3)] hover:text-[var(--tx2)]'
                }`}
              >
                {tab.icon}
                {tab.label}
                <span className={`ml-1 text-[10px] px-1.5 py-0.5 rounded-full font-bold ${
                  activeTab === tab.id ? 'bg-[var(--blue-bg)] text-[var(--blue-tx)]' : 'bg-[var(--surf2)] text-[var(--tx3)]'
                }`}>{tab.count}</span>
              </button>
            ))}
          </div>

          <div className="flex items-center gap-2 bg-[var(--surf2)] border border-[var(--b)] rounded-lg px-3 py-2 min-w-[220px]">
            <Search size={12} className="text-[var(--tx3)] flex-shrink-0" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder={`Search ${activeTab === 'students' ? 'students' : activeTab === 'staff' ? 'staff' : 'logs'}...`}
              className="flex-1 bg-transparent text-[12px] text-[var(--tx)] placeholder:text-[var(--tx3)] outline-none"
            />
            {search && (
              <button onClick={() => setSearch('')} className="text-[var(--tx3)] hover:text-[var(--tx)] cursor-pointer">
                <X size={12} />
              </button>
            )}
          </div>
        </div>

        {/* Students Tab */}
        {activeTab === 'students' && (
          <>
            {loadingStudents ? (
              <div className="flex flex-col items-center justify-center py-16 gap-3 text-[var(--tx3)]">
                <Loader2 size={22} className="animate-spin text-[var(--blue-tx)]" />
                <span className="text-[12px]">Loading deleted students...</span>
              </div>
            ) : filteredStudents.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 gap-3">
                <div className="w-14 h-14 rounded-2xl bg-[var(--teal-bg)] flex items-center justify-center">
                  <GraduationCap size={22} className="text-[var(--teal-tx)]" />
                </div>
                <div className="text-[13px] font-semibold text-[var(--tx)]">
                  {search ? 'No matching deleted students' : 'Recycle bin is empty'}
                </div>
                <div className="text-[11.5px] text-[var(--tx3)]">
                  {search ? 'Try a different search term.' : 'No students have been marked as "Left".'}
                </div>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full border-collapse text-[12px] min-w-[620px]">
                  <thead>
                    <tr className="border-b border-[var(--b)]">
                      {['Student', 'Roll No', 'Class', 'Parent / Guardian', 'Phone', 'Status', 'Actions'].map(h => (
                        <th key={h} className="text-[10.5px] font-medium text-[var(--tx3)] text-left px-2 py-2 whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredStudents.map(s => (
                      <tr key={s.id} className="border-b border-[var(--b)] hover:bg-[var(--surf2)] transition-colors last:border-0">
                        <td className="px-2 py-2.5">
                          <div className="flex items-center gap-2.5">
                            <div className="w-7 h-7 rounded-lg bg-[var(--red-bg)] flex items-center justify-center text-[10px] font-bold text-[var(--red-tx)]">
                              {s.name.slice(0, 2).toUpperCase()}
                            </div>
                            <div>
                              <div className="font-semibold text-[var(--tx)] flex items-center gap-1.5">
                                {s.name}
                                {s.isAlumni && <span className="px-1.5 py-0.5 text-[9px] bg-[var(--blue-bg)] text-[var(--blue-tx)] rounded border border-[var(--blue-tx)]/20 uppercase tracking-wider font-bold">Alumni</span>}
                              </div>
                              <div className="text-[10px] text-[var(--tx3)]">{s.gender}</div>
                            </div>
                          </div>
                        </td>
                        <td className="px-2 py-2.5 font-mono text-[11px] text-[var(--tx2)]">{s.roll}</td>
                        <td className="px-2 py-2.5 text-[var(--tx2)]">Class {s.class} — {s.section}</td>
                        <td className="px-2 py-2.5">
                          <div className="font-medium text-[var(--tx)]">{s.parent}</div>
                          <div className="text-[10px] text-[var(--tx3)]">{s.phone}</div>
                        </td>
                        <td className="px-2 py-2.5 text-[var(--tx2)]">{s.phone}</td>
                        <td className="px-2 py-2.5">
                          <Badge variant="red">{s.isAlumni ? 'Deleted' : 'Left'}</Badge>
                        </td>
                        <td className="px-2 py-2.5">
                          <div className="flex items-center gap-1.5">
                            <button
                              onClick={() => setConfirm({ type: 'restore', entity: 'student', id: s.id, name: s.name, isAlumni: s.isAlumni })}
                              className="flex items-center gap-1 px-2.5 py-1.5 text-[11px] font-semibold bg-[var(--teal-bg)] text-[var(--teal-tx)] rounded-lg hover:opacity-80 cursor-pointer transition-opacity"
                              title={s.isAlumni ? "Restore alumni" : "Restore student"}
                            >
                              <RotateCcw size={11} /> Restore
                            </button>
                            <button
                              onClick={() => setConfirm({ type: 'delete', entity: 'student', id: s.id, name: s.name, isAlumni: s.isAlumni })}
                              className="flex items-center gap-1 px-2.5 py-1.5 text-[11px] font-semibold bg-[var(--red-bg)] text-[var(--red-tx)] rounded-lg hover:opacity-80 cursor-pointer transition-opacity"
                              title="Delete permanently"
                            >
                              <Trash2 size={11} /> Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            {!loadingStudents && filteredStudents.length > 0 && (
              <div className="mt-3 pt-3 border-t border-[var(--b)] text-[11px] text-[var(--tx3)]">
                Showing {filteredStudents.length} of {deletedStudents.length} deleted student{deletedStudents.length !== 1 ? 's' : ''}
              </div>
            )}
          </>
        )}

        {/* Staff Tab */}
        {activeTab === 'staff' && (
          <>
            {loadingStaff ? (
              <div className="flex flex-col items-center justify-center py-16 gap-3 text-[var(--tx3)]">
                <Loader2 size={22} className="animate-spin text-[var(--blue-tx)]" />
                <span className="text-[12px]">Loading deleted staff...</span>
              </div>
            ) : filteredStaff.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 gap-3">
                <div className="w-14 h-14 rounded-2xl bg-[var(--teal-bg)] flex items-center justify-center">
                  <Users size={22} className="text-[var(--teal-tx)]" />
                </div>
                <div className="text-[13px] font-semibold text-[var(--tx)]">
                  {search ? 'No matching deleted staff' : 'Recycle bin is empty'}
                </div>
                <div className="text-[11.5px] text-[var(--tx3)]">
                  {search ? 'Try a different search term.' : 'No staff members have been removed.'}
                </div>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full border-collapse text-[12px] min-w-[580px]">
                  <thead>
                    <tr className="border-b border-[var(--b)]">
                      {['Staff Member', 'Designation', 'Department', 'Phone / Email', 'Status', 'Actions'].map(h => (
                        <th key={h} className="text-[10.5px] font-medium text-[var(--tx3)] text-left px-2 py-2 whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredStaff.map(s => (
                      <tr key={s.id} className="border-b border-[var(--b)] hover:bg-[var(--surf2)] transition-colors last:border-0">
                        <td className="px-2 py-2.5">
                          <div className="flex items-center gap-2.5">
                            <div className="w-7 h-7 rounded-lg bg-[var(--amber-bg)] flex items-center justify-center text-[10px] font-bold text-[var(--amber-tx)]">
                              {s.name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase()}
                            </div>
                            <div className="font-semibold text-[var(--tx)]">{s.name}</div>
                          </div>
                        </td>
                        <td className="px-2 py-2.5 text-[var(--tx2)]">{s.designation}</td>
                        <td className="px-2 py-2.5 text-[var(--tx2)]">{s.department}</td>
                        <td className="px-2 py-2.5">
                          <div className="text-[var(--tx)]">{s.phone}</div>
                          <div className="text-[10px] text-[var(--tx3)]">{s.email}</div>
                        </td>
                        <td className="px-2 py-2.5">
                          <Badge variant="amber">Resigned</Badge>
                        </td>
                        <td className="px-2 py-2.5">
                          <div className="flex items-center gap-1.5">
                            <button
                              onClick={() => setConfirm({ type: 'restore', entity: 'staff', id: s.id, name: s.name })}
                              className="flex items-center gap-1 px-2.5 py-1.5 text-[11px] font-semibold bg-[var(--teal-bg)] text-[var(--teal-tx)] rounded-lg hover:opacity-80 cursor-pointer transition-opacity"
                              title="Restore staff member"
                            >
                              <RotateCcw size={11} /> Restore
                            </button>
                            <button
                              onClick={() => setConfirm({ type: 'delete', entity: 'staff', id: s.id, name: s.name })}
                              className="flex items-center gap-1 px-2.5 py-1.5 text-[11px] font-semibold bg-[var(--red-bg)] text-[var(--red-tx)] rounded-lg hover:opacity-80 cursor-pointer transition-opacity"
                              title="Delete permanently"
                            >
                              <Trash2 size={11} /> Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            {!loadingStaff && filteredStaff.length > 0 && (
              <div className="mt-3 pt-3 border-t border-[var(--b)] text-[11px] text-[var(--tx3)]">
                Showing {filteredStaff.length} of {deletedStaff.length} deleted staff member{deletedStaff.length !== 1 ? 's' : ''}
              </div>
            )}
          </>
        )}

        {/* Activity Logs Tab */}
        {activeTab === 'activity_logs' && (
          <>
            {loadingActivityLogs ? (
              <div className="flex flex-col items-center justify-center py-16 gap-3 text-[var(--tx3)]">
                <Loader2 size={22} className="animate-spin text-[var(--blue-tx)]" />
                <span className="text-[12px]">Loading recycled activity logs...</span>
              </div>
            ) : filteredActivityLogs.length === 0 ? (
