interface StaffPayroll {
  id: string;
  userId?: string;
  name: string;
  init: string;
  designation: string;
  basic: number;
  hra: number;
  allowances: number;
  deductions: number;
  gross: number;
  net: number;
  status: 'Paid' | 'Pending' | 'On Hold';
  month: string;
}



