          const amt = getComponentAmt(c, salaries, basic, fallback, lop);
          if (c.type === 'earning') gross += amt;
          else totalDeductions += amt;
        });
        const net = Math.max(0, gross - totalDeductions);

        return {
          id: `virtual-${s.id}`,
          userId: s.id,
          name: s.name,
          init,
          designation: s.designation,
          basic,
          hra,
          allowances,
          deductions,
          gross,
          net,
          status: 'Pending' as const,
          month: monthFilter
