  const handleSetCurrent = async (ay: AcademicYear) => {
    setLoadingAys(true);
    try {
      await api.updateResource('academic-years', ay.id, { is_current: true });
      setSelectedAcademicYearId(ay.id);
      await loadAys();

      // Reload page context academic years
      window.location.reload();
