          disabled={loading}
          className="flex items-center justify-center p-2 text-[var(--tx2)] hover:text-[var(--tx)] border border-[var(--b)] rounded-xl bg-[var(--surf2)] hover:bg-[var(--surf3)] cursor-pointer disabled:opacity-50"
          title="Refresh logs"
