                      <span className="text-[10px] px-2 py-0.5 rounded-full bg-[var(--surf2)] text-[var(--tx3)]">
                        {log.subject_type}
                      </span>
                    )}
                    {log.properties?.ip_address && (
                      <span className="text-[10px] px-2 py-0.5 rounded-full bg-[var(--surf2)] text-[var(--tx3)]">
                        {log.properties.ip_address}
